{"command":"cd /tmp/t && cat > compact.py <<'EOF'
import sys, json
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try:
        d = json.loads(line)
    except Exception:
        print(line); continue
    p = d.get("payload", {})
    if "details" not in p and "valid" in p and "evaluationPath" not in p:
        print("FLAG valid=%s" % p["valid"]); continue
    def show(u, depth):
        extra = []
        if "annotations" in u: extra.append("ann=" + json.dumps(u["annotations"]))
        if "droppedAnnotations" in u: extra.append("drop=" + json.dumps(u["droppedAnnotations"]))
        if "errors" in u: extra.append("err=" + json.dumps(u["errors"]))
        print("  "*depth + "%s | %s | %s | %s %s" % (u.get("evaluationPath","?"), u.get("instanceLocation","?"), u.get("schemaLocation","?").split("#")[-1], "V" if u.get("valid") else "X", " ".join(extra)))
        for c in u.get("details", []):
            show(c, depth+1)
    if d.get("output") == "hierarchical":
        show(p, 0)
    else:
        print("valid=%s" % p.get("valid"))
        for u in p.get("details", []):
            show(u, 1)
EOF
