{"command":"mkdir -p /workspace/src && cat > /workspace/src/num.rs <<'EOF'
//! Exact decimal arithmetic used for numeric keywords.
//!
//! JSON numbers are kept in their textual form by `serde_json` (arbitrary
//! precision). This module provides an exact decimal representation together
//! with the classification rules used by the validator.

use std::cmp::Ordering;

/// Arbitrary precision unsigned integer, little-endian limbs in base 10^9.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BigUint {
    limbs: Vec<u32>,
}

const BASE: u64 = 1_000_000_000;

impl BigUint {
    pub fn zero() -> Self {
        BigUint { limbs: Vec::new() }
    }

    pub fn is_zero(&self) -> bool {
        self.limbs.is_empty()
    }

    fn trim(&mut self) {
        while let Some(&0) = self.limbs.last() {
            self.limbs.pop();
        }
    }

    /// Parse a string of ASCII digits.
    pub fn from_digits(digits: &str) -> Self {
        let bytes = digits.as_bytes();
        let mut limbs = Vec::with_capacity(bytes.len() / 9 + 1);
        let mut end = bytes.len();
        while end > 0 {
            let start = end.saturating_sub(9);
            let mut v: u32 = 0;
            for &b in &bytes[start..end] {
                v = v * 10 + (b - b'0') as u32;
            }
            limbs.push(v);
            end = start;
        }
        let mut n = BigUint { limbs };
        n.trim();
        n
    }

    pub fn from_u128(mut v: u128) -> Self {
        let mut limbs = Vec::new();
        while v > 0 {
            limbs.push((v % BASE as u128) as u32);
            v /= BASE as u128;
        }
        BigUint { limbs }
    }

    /// Number of decimal digits (0 for zero).
    pub fn digit_count(&self) -> i64 {
        match self.limbs.last() {
            None => 0,
            Some(&top) => {
                let mut d = 0i64;
                let mut t = top;
                while t > 0 {
                    d += 1;
                    t /= 10;
                }
                d + (self.limbs.len() as i64 - 1) * 9
            }
        }
    }

    pub fn to_u128(&self) -> Option<u128> {
        let mut v: u128 = 0;
        for &l in self.limbs.iter().rev() {
            v = v.checked_mul(BASE as u128)?.checked_add(l as u128)?;
        }
        Some(v)
    }

    pub fn mul_small(&self, m: u32) -> BigUint {
        if m == 0 || self.is_zero() {
            return BigUint::zero();
        }
        let mut out = Vec::with_capacity(self.limbs.len() + 1);
        let mut carry: u64 = 0;
        for &l in &self.limbs {
            let v = l as u64 * m as u64 + carry;
            out.push((v % BASE) as u32);
            carry = v / BASE;
        }
        while carry > 0 {
            out.push((carry % BASE) as u32);
            carry /= BASE;
        }
        let mut n = BigUint { limbs: out };
        n.trim();
        n
    }

    pub fn add_small(&self, a: u32) -> BigUint {
        let mut out = self.limbs.clone();
        let mut carry = a as u64;
        let mut i = 0;
        while carry > 0 {
            if i == out.len() {
                out.push(0);
            }
            let v = out[i] as u64 + carry;
            out[i] = (v % BASE) as u32;
            carry = v / BASE;
            i += 1;
        }
        let mut n = BigUint { limbs: out };
        n.trim();
        n
    }

    /// Multiply by 10^k.
    pub fn mul_pow10(&self, k: u64) -> BigUint {
        if self.is_zero() {
            return BigUint::zero();
        }
        let whole = (k / 9) as usize;
        let rem = (k % 9) as u32;
        let mut limbs = vec![0u32; whole];
        limbs.extend_from_slice(&self.limbs);
        let n = BigUint { limbs };
        if rem == 0 {
            n
        } else {
            n.mul_small(10u32.pow(rem))
        }
    }

    pub fn sub(&self, other: &BigUint) -> BigUint {
        // assumes self >= other
        let mut out = Vec::with_capacity(self.limbs.len());
        let mut borrow: i64 = 0;
        for i in 0..self.limbs.len() {
            let a = self.limbs[i] as i64;
            let b = *other.limbs.get(i).unwrap_or(&0) as i64;
            let mut v = a - b - borrow;
            if v < 0 {
                v += BASE as i64;
                borrow = 1;
            } else {
                borrow = 0;
            }
            out.push(v as u32);
        }
        let mut n = BigUint { limbs: out };
        n.trim();
        n
    }

    /// Remainder of self divided by other (other must be non-zero).
    pub fn rem(&self, other: &BigUint) -> BigUint {
        if other.is_zero() {
            return BigUint::zero();
        }
        if self < other {
            return self.clone();
        }
        // Fast path: divisor fits in u64 (up to 2 limbs).
        if other.limbs.len() <= 2 {
            let d = other.to_u128().unwrap() as u64;
            let mut r: u128 = 0;
            for &l in self.limbs.iter().rev() {
                r = (r * BASE as u128 + l as u128) % d as u128;
            }
            return BigUint::from_u128(r);
        }
        // General: process limbs from the most significant.
        let mut r = BigUint::zero();
        for &l in self.limbs.iter().rev() {
            // r = r * BASE + l
            r = r.mul_small(BASE as u32).add_small(l);
            if &r >= other {
                // find q in [1, BASE) with q*other <= r < (q+1)*other, by binary search
                let mut lo: u64 = 1;
                let mut hi: u64 = BASE - 1;
                while lo < hi {
                    let mid = (lo + hi + 1) / 2;
                    let prod = other.mul_small(mid as u32);
                    if prod <= r {
                        lo = mid;
                    } else {
                        hi = mid - 1;
                    }
                }
                let prod = other.mul_small(lo as u32);
                r = r.sub(&prod);
            }
        }
        r
    }
}

impl PartialOrd for BigUint {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for BigUint {
    fn cmp(&self, other: &Self) -> Ordering {
        match self.limbs.len().cmp(&other.limbs.len()) {
            Ordering::Equal => {}
            o => return o,
        }
        for i in (0..self.limbs.len()).rev() {
            match self.limbs[i].cmp(&other.limbs[i]) {
                Ordering::Equal => {}
                o => return o,
            }
        }
        Ordering::Equal
    }
}

/// Exact decimal: value = (-1)^neg * mant * 10^exp, normalized so that `mant`
/// has no trailing zero digits (zero is represented with mant = 0, exp = 0).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Decimal {
    pub neg: bool,
    pub mant: BigUint,
    pub exp: i64,
}

impl Decimal {
    /// Parse a JSON number literal.
    pub fn parse(text: &str) -> Option<Decimal> {
        let bytes = text.as_bytes();
        let mut i = 0;
        let mut neg = false;
        if i < bytes.len() && (bytes[i] == b'-' || bytes[i] == b'+') {
            neg = bytes[i] == b'-';
            i += 1;
        }
        let mut digits = String::new();
        let mut exp: i64 = 0;
        let mut seen_digit = false;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            digits.push(bytes[i] as char);
            seen_digit = true;
            i += 1;
        }
        if i < bytes.len() && bytes[i] == b'.' {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                digits.push(bytes[i] as char);
                exp -= 1;
                seen_digit = true;
                i += 1;
            }
        }
        if !seen_digit {
            return None;
        }
        if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
            i += 1;
            let mut eneg = false;
            if i < bytes.len() && (bytes[i] == b'-' || bytes[i] == b'+') {
                eneg = bytes[i] == b'-';
                i += 1;
            }
            let mut e: i64 = 0;
            let mut seen = false;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                e = e.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
                seen = true;
                i += 1;
            }
            if !seen {
                return None;
            }
            exp = exp.saturating_add(if eneg { -e } else { e });
        }
        if i != bytes.len() {
            return None;
        }
        // strip leading zeros
        let trimmed = digits.trim_start_matches('0');
        let mut d = Decimal {
            neg,
            mant: BigUint::from_digits(trimmed),
            exp,
        };
        d.normalize_from_digits(trimmed);
        Some(d)
    }

    fn normalize_from_digits(&mut self, digits: &str) {
        if self.mant.is_zero() {
            self.exp = 0;
            self.neg = false;
            return;
        }
        // strip trailing zeros
        let trailing = digits.len() - digits.trim_end_matches('0').len();
        if trailing > 0 {
            self.mant = BigUint::from_digits(&digits[..digits.len() - trailing]);
            self.exp = self.exp.saturating_add(trailing as i64);
        }
    }

    pub fn is_zero(&self) -> bool {
        self.mant.is_zero()
    }

    pub fn is_integer(&self) -> bool {
        self.mant.is_zero() || self.exp >= 0
    }

    /// Integer value as i128 if it is an integer that fits.
    pub fn to_i128(&self) -> Option<i128> {
        if !self.is_integer() {
            return None;
        }
        if self.mant.is_zero() {
            return Some(0);
        }
        if self.exp > 40 {
            return None;
        }
        let m = self.mant.mul_pow10(self.exp as u64).to_u128()?;
        if m > i128::MAX as u128 {
            return None;
        }
        let v = m as i128;
        Some(if self.neg { -v } else { v })
    }

    /// Exact comparison.
    pub fn cmp(&self, other: &Decimal) -> Ordering {
        let sa = if self.is_zero() { 0 } else if self.neg { -1 } else { 1 };
        let sb = if other.is_zero() { 0 } else if other.neg { -1 } else { 1 };
        if sa != sb {
            return sa.cmp(&sb);
        }
        if sa == 0 {
            return Ordering::Equal;
        }
        let mag = Self::cmp_magnitude(self, other);
        if sa < 0 {
            mag.reverse()
        } else {
            mag
        }
    }

    fn cmp_magnitude(a: &Decimal, b: &Decimal) -> Ordering {
        // compare adjusted exponents (number of integer digits)
        let adj_a = a.mant.digit_count() + a.exp;
        let adj_b = b.mant.digit_count() + b.exp;
        match adj_a.cmp(&adj_b) {
            Ordering::Equal => {}
            o => return o,
        }
        // Same magnitude; align exponents.
        if a.exp == b.exp {
            a.mant.cmp(&b.mant)
        } else if a.exp > b.exp {
            let shifted = a.mant.mul_pow10((a.exp - b.exp) as u64);
            shifted.cmp(&b.mant)
        } else {
            let shifted = b.mant.mul_pow10((b.exp - a.exp) as u64);
            a.mant.cmp(&shifted)
        }
    }

    /// Whether `self` is an exact multiple of `other`.
    pub fn is_multiple_of(&self, other: &Decimal) -> bool {
        if other.is_zero() {
            return false;
        }
        if self.is_zero() {
            return true;
        }
        let d = self.exp - other.exp;
        if d >= 0 {
            if d > 1_000_000 {
                // unrealistically large; approximate via digit reasoning
                return false;
            }
            let x = self.mant.mul_pow10(d as u64);
            x.rem(&other.mant).is_zero()
        } else {
            let shift = (-d) as u64;
            // other.mant * 10^shift must divide self.mant; quick magnitude check
            if other.mant.digit_count() + shift as i64 > self.mant.digit_count() {
                return false;
            }
            let y = other.mant.mul_pow10(shift);
            self.mant.rem(&y).is_zero()
        }
    }
}

/// Classification of a JSON number for comparison purposes.
#[derive(Clone, Debug)]
pub struct Num {
    pub dec: Decimal,
    pub f: f64,
    pub text: String,
}

impl Num {
    pub fn from_json(n: &serde_json::Number) -> Num {
        let text = n.to_string();
        let dec = Decimal::parse(&text).unwrap_or(Decimal {
            neg: false,
            mant: BigUint::zero(),
            exp: 0,
        });
        let f = text.parse::<f64>().unwrap_or(0.0);
        Num { dec, f, text }
    }

    pub fn is_integer(&self) -> bool {
        self.dec.is_integer()
    }
}

/// Compare an instance number with a limit according to the validator rules:
/// integer-valued limits compare exactly against integer instances and via
/// f64 against non-integer instances; non-integer limits compare exactly.
pub fn compare(instance: &Num, limit: &Num) -> Ordering {
    if limit.is_integer() {
        if instance.is_integer() {
            instance.dec.cmp(&limit.dec)
        } else {
            instance.f.partial_cmp(&limit.f).unwrap_or(Ordering::Equal)
        }
    } else {
        instance.dec.cmp(&limit.dec)
    }
}

pub fn is_multiple_of(instance: &Num, limit: &Num) -> bool {
    if limit.is_integer() {
        if instance.is_integer() {
            instance.dec.is_multiple_of(&limit.dec)
        } else {
            let q = instance.f / limit.f;
            q.is_finite() && q.fract() == 0.0
        }
    } else {
        instance.dec.is_multiple_of(&limit.dec)
    }
}

