pub fn num_eq(a: &serde_json::Number, b: &serde_json::Number) -> bool {
    if a == b {
        return true;
    }
    let da = Decimal::parse(&a.to_string());
    let db = Decimal::parse(&b.to_string());
    match (da, db) {
        (Some(x), Some(y)) => x == y,
        _ => false,
    }
}

