//! Strict RFC 3986 URI reference parsing, resolution and normalization.

use std::fmt;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UriRef {
    pub scheme: Option<String>,
    pub authority: Option<String>,
    pub path: String,
    pub query: Option<String>,
    pub fragment: Option<String>,
}

#[derive(Debug, Clone)]
pub enum UriError {
    UnexpectedChar(usize),
    InvalidPercent(usize),
}

impl fmt::Display for UriError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UriError::UnexpectedChar(i) => write!(f, "unexpected character at index {}", i),
            UriError::InvalidPercent(i) => write!(f, "invalid percent-encoded octet at index {}", i),
        }
    }
}

fn is_unreserved(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~')
}

fn is_sub_delim(b: u8) -> bool {
    matches!(b, b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';' | b'=')
}

fn is_pchar_plain(b: u8) -> bool {
    is_unreserved(b) || is_sub_delim(b) || b == b':' || b == b'@'
}

struct Scanner<'a> {
    s: &'a [u8],
}

impl<'a> Scanner<'a> {
    /// Validate a run of characters satisfying `ok` (with percent-encoding
    /// allowed) starting at `start`, stopping at the first byte that is not
    /// acceptable. Returns the end index.
    fn scan(&self, start: usize, ok: &dyn Fn(u8) -> bool) -> Result<usize, UriError> {
        let mut i = start;
        while i < self.s.len() {
            let b = self.s[i];
