    }
}

/// Parse a URI reference strictly.
pub fn parse(input: &str) -> Result<UriRef, UriError> {
    let s = input.as_bytes();
    let sc = Scanner { s };
    let mut i = 0usize;
    let mut scheme = None;

    // Scheme detection: a ':' before any '/', '?', '#'.
    let mut colon = None;
    for (idx, &b) in s.iter().enumerate() {
        if b == b':' {
            colon = Some(idx);
            break;
        }
        if b == b'/' || b == b'?' || b == b'#' {
            break;
        }
    }
    if let Some(c) = colon {
        // validate scheme
        if c == 0 || !s[0].is_ascii_alphabetic() {
            return Err(UriError::UnexpectedChar(0));
        }
        for (idx, &b) in s[..c].iter().enumerate() {
            if !(b.is_ascii_alphanumeric() || matches!(b, b'+' | b'-' | b'.')) {
                return Err(UriError::UnexpectedChar(idx));
            }
        }
        scheme = Some(String::from_utf8_lossy(&s[..c]).to_string());
        i = c + 1;
    }

    let mut authority = None;
    if i + 1 < s.len() + 1 && s.len() >= i + 2 && s[i] == b'/' && s[i + 1] == b'/' {
        let start = i + 2;
        // authority: userinfo@host:port
        let mut j = start;
        // userinfo and reg-name chars
        let auth_ok = |b: u8| is_unreserved(b) || is_sub_delim(b) || b == b':' || b == b'@';
        if j < s.len() && s[j] == b'[' {
            // IP literal
            j += 1;
            while j < s.len() && (s[j].is_ascii_hexdigit() || matches!(s[j], b':' | b'.')) {
                j += 1;
            }
            if j >= s.len() || s[j] != b']' {
                return Err(UriError::UnexpectedChar(j));
            }
            j += 1;
            // optional port
            if j < s.len() && s[j] == b':' {
                j += 1;
                while j < s.len() && s[j].is_ascii_digit() {
                    j += 1;
                }
            }
        } else {
            j = sc.scan(j, &auth_ok)?;
            // Validate port if present: after the last ':' (not inside userinfo)
            let auth = &s[start..j];
            let at = auth.iter().rposition(|&b| b == b'@');
            let hostport = match at {
                Some(a) => &auth[a + 1..],
                None => auth,
            };
            if let Some(cp) = hostport.iter().rposition(|&b| b == b':') {
                let port = &hostport[cp + 1..];
                for (k, &b) in port.iter().enumerate() {
