                    }
                }
            }
        }
        if j < s.len() && !matches!(s[j], b'/' | b'?' | b'#') {
            return Err(UriError::UnexpectedChar(j));
        }
        authority = Some(String::from_utf8_lossy(&s[start..j]).to_string());
        i = j;
    }

    // path
    let path_ok = |b: u8| is_pchar_plain(b) || b == b'/';
    let path_start = i;
    let j = sc.scan(i, &path_ok)?;
    if j < s.len() && !matches!(s[j], b'?' | b'#') {
        return Err(UriError::UnexpectedChar(j));
    }
    let path = String::from_utf8_lossy(&s[path_start..j]).to_string();
    i = j;

    let mut query = None;
    if i < s.len() && s[i] == b'?' {
        let qs = i + 1;
        let q_ok = |b: u8| is_pchar_plain(b) || b == b'/' || b == b'?';
