    Ok(UriRef {
        scheme,
        authority,
        path,
        query,
        fragment,
    })
}

fn remove_dot_segments(path: &str) -> String {
    let mut input = path.to_string();
    let mut output = String::new();
    while !input.is_empty() {
        if input.starts_with("../") {
            input = input[3..].to_string();
        } else if input.starts_with("./") {
            input = input[2..].to_string();
        } else if input.starts_with("/./") {
            input = format!("/{}", &input[3..]);
        } else if input == "/." {
            input = "/".to_string();
        } else if input.starts_with("/../") {
            input = format!("/{}", &input[4..]);
            if let Some(pos) = output.rfind('/') {
                output.truncate(pos);
            } else {
                output.clear();
            }
        } else if input == "/.." {
            input = "/".to_string();
            if let Some(pos) = output.rfind('/') {
                output.truncate(pos);
            } else {
                output.clear();
            }
        } else if input == "." || input == ".." {
            input.clear();
        } else {
            // move first path segment (including initial '/' if any) to output
            let start = if input.starts_with('/') { 1 } else { 0 };
            let end = match input[start..].find('/') {
                Some(p) => start + p,
                None => input.len(),
            };
            output.push_str(&input[..end]);
            input = input[end..].to_string();
        }
    }
    output
}

fn merge(base: &UriRef, rel_path: &str) -> String {
    if base.authority.is_some() && base.path.is_empty() {
        format!("/{}", rel_path)
    } else {
        match base.path.rfind('/') {
            Some(pos) => format!("{}{}", &base.path[..=pos], rel_path),
            None => rel_path.to_string(),
        }
    }
}

/// Resolve `reference` against `base` (RFC 3986 section 5.2.2).
pub fn resolve(base: &UriRef, reference: &UriRef) -> UriRef {
    let mut t = UriRef {
        scheme: None,
        authority: None,
        path: String::new(),
        query: None,
        fragment: None,
    };
    if reference.scheme.is_some() {
        t.scheme = reference.scheme.clone();
        t.authority = reference.authority.clone();
        t.path = remove_dot_segments(&reference.path);
        t.query = reference.query.clone();
    } else {
        if reference.authority.is_some() {
            t.authority = reference.authority.clone();
            t.path = remove_dot_segments(&reference.path);
            t.query = reference.query.clone();
        } else {
            if reference.path.is_empty() {
                t.path = base.path.clone();
                t.query = if reference.query.is_some() {
                    reference.query.clone()
                } else {
                    base.query.clone()
                };
            } else {
                if reference.path.starts_with('/') {
                    t.path = remove_dot_segments(&reference.path);
                } else {
                    t.path = remove_dot_segments(&merge(base, &reference.path));
                }
                t.query = reference.query.clone();
            }
            t.authority = base.authority.clone();
        }
        t.scheme = base.scheme.clone();
    }
    t.fragment = reference.fragment.clone();
    t
}

/// Normalize: lowercase scheme and host.
pub fn normalize(u: &mut UriRef) {
    if let Some(s) = &u.scheme {
        u.scheme = Some(s.to_ascii_lowercase());
    }
    if let Some(a) = &u.authority {
        // lowercase host part only (between optional userinfo@ and :port)
        let (userinfo, rest) = match a.rfind('@') {
            Some(p) => (Some(&a[..p]), &a[p + 1..]),
            None => (None, a.as_str()),
        };
        let (host, port) = if rest.starts_with('[') {
            match rest.find(']') {
                Some(p) => (&rest[..=p], &rest[p + 1..]),
                None => (rest, ""),
            }
        } else {
            match rest.rfind(':') {
                Some(p) => (&rest[..p], &rest[p..]),
                None => (rest, ""),
            }
        };
        let mut out = String::new();
        if let Some(ui) = userinfo {
            out.push_str(ui);
            out.push('@');
        }
        out.push_str(&host.to_ascii_lowercase());
        out.push_str(port);
        u.authority = Some(out);
    }
}

impl UriRef {
    /// Serialize without fragment.
    pub fn to_string_no_fragment(&self) -> String {
        let mut out = String::new();
        if let Some(s) = &self.scheme {
            out.push_str(s);
            out.push(':');
        }
        if let Some(a) = &self.authority {
            out.push_str("//");
            out.push_str(a);
        }
        out.push_str(&self.path);
        if let Some(q) = &self.query {
            out.push('?');
            out.push_str(q);
        }
        out
    }

    pub fn to_full_string(&self) -> String {
        let mut out = self.to_string_no_fragment();
        if let Some(f) = &self.fragment {
            out.push('#');
            out.push_str(f);
        }
        out
    }
}

impl fmt::Display for UriRef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_full_string())
    }
}

/// Percent-decode a string (lossy UTF-8).
pub fn percent_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() + 0 || (bytes[i] == b'%' && i + 2 == bytes.len() - 0 - 0 && false) {
            // handled below
        }
        if bytes[i] == b'%' && i + 2 <= bytes.len() - 1 + 0 && bytes.len() > i + 2 {
            let h = (bytes[i + 1] as char).to_digit(16);
            let l = (bytes[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (h, l) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

