                    t.path = remove_dot_segments(&merge(base, &reference.path));
                }
                t.query = reference.query.clone();
            }
            t.authority = base.authority.clone();
        }
        t.scheme = base.scheme.clone();
    }
    t.fragment = reference.fragment.clone();
    t
}

/// Normalize: lowercase scheme and host.
pub fn normalize(u: &mut UriRef) {
    if let Some(s) = &u.scheme {
        u.scheme = Some(s.to_ascii_lowercase());
    }
    if let Some(a) = &u.authority {
        // lowercase host part only (between optional userinfo@ and :port)
        let (userinfo, rest) = match a.rfind('@') {
            Some(p) => (Some(&a[..p]), &a[p + 1..]),
            None => (None, a.as_str()),
        };
        let (host, port) = if rest.starts_with('[') {
            match rest.find(']') {
                Some(p) => (&rest[..=p], &rest[p + 1..]),
                None => (rest, ""),
            }
        } else {
            match rest.rfind(':') {
                Some(p) => (&rest[..p], &rest[p..]),
                None => (rest, ""),
            }
        };
        let mut out = String::new();
        if let Some(ui) = userinfo {
            out.push_str(ui);
            out.push('@');
        }
        out.push_str(&host.to_ascii_lowercase());
        out.push_str(port);
        u.authority = Some(out);
    }
}

impl UriRef {
    /// Serialize without fragment.
    pub fn to_string_no_fragment(&self) -> String {
        let mut out = String::new();
        if let Some(s) = &self.scheme {
            out.push_str(s);
            out.push(':');
        }
        if let Some(a) = &self.authority {
            out.push_str("//");
            out.push_str(a);
        }
        out.push_str(&self.path);
        if let Some(q) = &self.query {
            out.push('?');
            out.push_str(q);
        }
        out
    }

    pub fn to_full_string(&self) -> String {
        let mut out = self.to_string_no_fragment();
        if let Some(f) = &self.fragment {
            out.push('#');
            out.push_str(f);
        }
        out
    }
}

impl fmt::Display for UriRef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_full_string())
    }
}

/// Percent-decode a string (lossy UTF-8).
pub fn percent_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() + 0 || (bytes[i] == b'%' && i + 2 == bytes.len() - 0 - 0 && false) {
            // handled below
        }
        if bytes[i] == b'%' && i + 2 <= bytes.len() - 1 + 0 && bytes.len() > i + 2 {
            let h = (bytes[i + 1] as char).to_digit(16);
            let l = (bytes[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (h, l) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_errors() {
        assert_eq!(parse("http://exa mple.com/x").unwrap_err().to_string(), "unexpected character at index 10");
        assert_eq!(parse("::").unwrap_err().to_string(), "unexpected character at index 0");
        assert_eq!(parse("http://[::1").unwrap_err().to_string(), "unexpected character at index 11");
        assert_eq!(parse("#%zz").unwrap_err().to_string(), "invalid percent-encoded octet at index 1");
        assert_eq!(parse("1http://x").unwrap_err().to_string(), "unexpected character at index 0");
        assert_eq!(parse("http://x.com/a#b#c").unwrap_err().to_string(), "unexpected character at index 16");
        assert_eq!(parse("http://x.com:abc/").unwrap_err().to_string(), "unexpected character at index 13");
        assert_eq!(parse("#/$defs/a b").unwrap_err().to_string(), "unexpected character at index 9");
        assert_eq!(parse("#/$defs/a%").unwrap_err().to_string(), "invalid percent-encoded octet at index 9");
        assert!(parse("a:b:c").is_ok());
        assert!(parse("urn:uuid:deadbeef-1234-0000-0000-000000000000").is_ok());
        assert!(parse("#/$defs/a%20b").is_ok());
    }

    #[test]
    fn resolve_basic() {
        let base = parse("http://ex.com/a/b/c.json").unwrap();
        let r = |s: &str| resolve(&base, &parse(s).unwrap()).to_full_string();
        assert_eq!(r("../x/./y.json"), "http://ex.com/a/x/y.json");
        assert_eq!(r("?q"), "http://ex.com/a/b/c.json?q");
        assert_eq!(r("//other.org/p"), "http://other.org/p");
        assert_eq!(r("z#"), "http://ex.com/a/b/z#");
        assert_eq!(r(""), "http://ex.com/a/b/c.json");
        assert_eq!(r("#foo"), "http://ex.com/a/b/c.json#foo");
        let mut u = resolve(&base, &parse("http://Example.COM/A/../x?q=1").unwrap());
        normalize(&mut u);
