//! Resource registry: tracks schema documents, embedded resources (`$id`),
//! anchors, and resolves references (including remote retrieval).

use crate::draft::Draft;
use crate::uri::{self, UriRef};
use serde_json::Value;
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

#[derive(Clone)]
pub struct Resource {
    /// The (sub)schema value that forms this resource root.
    pub value: Rc<Value>,
    /// Base URI (no fragment).
    pub base: String,
    pub draft: Draft,
    /// The document this resource belongs to and the pointer inside it.
    pub doc: Rc<Value>,
    pub pointer: String,
}

#[derive(Clone)]
pub struct AnchorTarget {
    pub value: Rc<Value>,
    pub pointer: String,
    pub dynamic: bool,
}

pub struct FetchConfig {
    pub connect_timeout: Option<f64>,
    pub timeout: Option<f64>,
}

pub struct Registry {
    resources: RefCell<HashMap<String, Resource>>,
    anchors: RefCell<HashMap<String, HashMap<String, AnchorTarget>>>,
    /// base uri -> whether the resource root has `$recursiveAnchor: true`
    recursive_anchors: RefCell<HashMap<String, bool>>,
    pub fetch: FetchConfig,
    pub default_draft: Draft,
}

#[derive(Debug, Clone)]
pub struct RefError(pub String);

impl std::fmt::Display for RefError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

/// Resolved reference target.
pub struct Resolved {
    pub value: Rc<Value>,
    pub base: String,
    pub draft: Draft,
    /// JSON pointer within the resource's document ("" when the target is
    /// addressed by an anchor or is the resource root).
    pub pointer: String,
    pub doc: Rc<Value>,
}

fn walk_subschemas<'a>(draft: Draft, schema: &'a Value, f: &mut dyn FnMut(&'a Value, String)) {
    let obj = match schema.as_object() {
        Some(o) => o,
        None => return,
    };
    for (k, v) in obj {
        let kw: &str = k;
        let is_map = match kw {
            "properties" | "patternProperties" | "definitions" => true,
            "$defs" | "dependentSchemas" => matches!(draft, Draft::Draft201909 | Draft::Draft202012),
            "dependencies" => true,
            _ => false,
        };
        let is_array = match kw {
            "allOf" | "anyOf" | "oneOf" | "items" => true,
            "prefixItems" => matches!(draft, Draft::Draft202012),
            _ => false,
        };
        let is_single = match kw {
            "items" | "additionalItems" | "additionalProperties" | "not" => true,
            "contains" | "propertyNames" => draft != Draft::Draft4,
            "if" | "then" | "else" => !matches!(draft, Draft::Draft4 | Draft::Draft6),
            "unevaluatedItems" | "unevaluatedProperties" | "contentSchema" => {
                matches!(draft, Draft::Draft201909 | Draft::Draft202012)
            }
            _ => false,
        };
        if is_map {
            if let Some(m) = v.as_object() {
                for (pk, pv) in m {
                    if pv.is_object() || pv.is_boolean() {
                        f(pv, format!("/{}/{}", escape_pointer(kw), escape_pointer(pk)));
                    }
                }
            }
            continue;
        }
        if is_array {
            if let Some(arr) = v.as_array() {
                for (i, item) in arr.iter().enumerate() {
                    f(item, format!("/{}/{}", escape_pointer(kw), i));
                }
                continue;
            }
        }
        if is_single && (v.is_object() || v.is_boolean()) {
            f(v, format!("/{}", escape_pointer(kw)));
        }
    }
}

pub fn escape_pointer(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

pub fn unescape_pointer(s: &str) -> String {
    s.replace("~1", "/").replace("~0", "~")
}

impl Registry {
    pub fn new(default_draft: Draft, fetch: FetchConfig) -> Registry {
        Registry {
            resources: RefCell::new(HashMap::new()),
            anchors: RefCell::new(HashMap::new()),
            recursive_anchors: RefCell::new(HashMap::new()),
            fetch,
            default_draft,
        }
    }

    /// Register the built-in meta-schemas.
    pub fn add_meta_schemas(&self) -> Result<(), RefError> {
        for draft in Draft::all() {
            for (uri, text) in draft.meta_schemas() {
                let value: Value = serde_json::from_str(text).expect("valid meta-schema");
                let doc = Rc::new(value);
                self.add_document(uri, doc, draft)?;
            }
        }
        Ok(())
    }

    /// Add a document with the given base URI (no fragment) and draft.
    pub fn add_document(&self, base: &str, doc: Rc<Value>, draft: Draft) -> Result<(), RefError> {
        self.register(base, doc.clone(), doc, draft, String::new())
    }

    fn register(
        &self,
        base: &str,
        value: Rc<Value>,
        doc: Rc<Value>,
        draft: Draft,
        pointer: String,
    ) -> Result<(), RefError> {
        let res = Resource {
            value: value.clone(),
            base: base.to_string(),
            draft,
            doc: doc.clone(),
            pointer: pointer.clone(),
        };
        self.resources
            .borrow_mut()
            .entry(base.to_string())
            .or_insert(res);
        if let Some(obj) = value.as_object() {
            if let Some(Value::Bool(true)) = obj.get("$recursiveAnchor") {
                if draft == Draft::Draft201909 {
                    self.recursive_anchors.borrow_mut().insert(base.to_string(), true);
                }
            }
        }
        self.scan(base, &value, doc, draft, &pointer)
    }

    fn add_anchor(&self, base: &str, name: &str, target: AnchorTarget) {
        let mut anchors = self.anchors.borrow_mut();
        let m = anchors.entry(base.to_string()).or_default();
        m.entry(name.to_string()).or_insert(target);
    }

    /// Recursively scan a schema for embedded resources and anchors.
    fn scan(
        &self,
        base: &str,
        schema: &Rc<Value>,
        doc: Rc<Value>,
        draft: Draft,
        pointer: &str,
    ) -> Result<(), RefError> {
        let obj = match schema.as_object() {
            Some(o) => o,
            None => return Ok(()),
        };
        // anchors declared on this schema object
        if matches!(draft, Draft::Draft201909 | Draft::Draft202012) {
            if let Some(Value::String(a)) = obj.get("$anchor") {
                self.add_anchor(
                    base,
                    a,
                    AnchorTarget {
                        value: schema.clone(),
                        pointer: pointer.to_string(),
                        dynamic: false,
                    },
                );
            }
            if draft == Draft::Draft202012 {
                if let Some(Value::String(a)) = obj.get("$dynamicAnchor") {
                    self.add_anchor(
                        base,
                        a,
                        AnchorTarget {
                            value: schema.clone(),
                            pointer: pointer.to_string(),
                            dynamic: true,
                        },
                    );
                }
            }
        }
        let mut subs: Vec<(&Value, String)> = Vec::new();
        walk_subschemas(draft, schema, &mut |v, p| subs.push((v, p)));
        for (sub, rel) in subs {
            let sub_ptr = format!("{}{}", pointer, rel);
            let sub_rc = Rc::new(sub.clone());
            // Does this subschema declare a new resource / anchor via id?
            let mut new_base: Option<String> = None;
            let mut sub_draft = draft;
            if let Some(sobj) = sub.as_object() {
                if matches!(draft, Draft::Draft201909 | Draft::Draft202012) {
                    if let Some(Value::String(s)) = sobj.get("$schema") {
                        if let Some(d) = Draft::from_schema_uri(s) {
                            sub_draft = d;
                        }
                    }
                }
                if let Some(Value::String(id)) = sobj.get(draft.id_keyword()) {
                    let parsed = uri::parse(id)
                        .map_err(|e| RefError(format!("Invalid URI reference '{}': {}", id, e)))?;
                    let base_uri = uri::parse(base).unwrap_or(UriRef {
                        scheme: None,
                        authority: None,
                        path: String::new(),
                        query: None,
                        fragment: None,
                    });
                    let mut resolved = uri::resolve(&base_uri, &parsed);
                    uri::normalize(&mut resolved);
                    let frag = resolved.fragment.clone();
                    let no_frag = resolved.to_string_no_fragment();
                    let is_plain_anchor = frag.as_ref().map_or(false, |f| !f.is_empty() && !f.starts_with('/'));
                    if is_plain_anchor && draft.ref_ignores_siblings() {
                        // `$id: "#foo"` style plain-name fragment anchor.
                        if no_frag == base || parsed.scheme.is_none() && parsed.authority.is_none() && parsed.path.is_empty() && parsed.query.is_none() {
                            self.add_anchor(
                                base,
                                frag.as_deref().unwrap_or(""),
                                AnchorTarget {
                                    value: sub_rc.clone(),
                                    pointer: sub_ptr.clone(),
                                    dynamic: false,
                                },
                            );
                        } else {
                            new_base = Some(no_frag.clone());
                            self.add_anchor(
                                &no_frag,
                                frag.as_deref().unwrap_or(""),
                                AnchorTarget {
                                    value: sub_rc.clone(),
                                    pointer: sub_ptr.clone(),
                                    dynamic: false,
                                },
                            );
                        }
                    } else if no_frag != base || frag.as_ref().map_or(false, |f| f.is_empty()) {
                        if no_frag != base {
                            new_base = Some(no_frag);
                        }
                    }
                }
            }
            match new_base {
                Some(nb) => {
                    self.register(&nb, sub_rc, doc.clone(), sub_draft, sub_ptr)?;
                }
                None => {
                    self.scan(base, &sub_rc, doc.clone(), sub_draft, &sub_ptr)?;
                }
            }
        }
        Ok(())
    }

    pub fn has_resource(&self, base: &str) -> bool {
        self.resources.borrow().contains_key(base)
    }

    pub fn get_resource(&self, base: &str) -> Option<Resource> {
        self.resources.borrow().get(base).cloned()
    }

    pub fn has_recursive_anchor(&self, base: &str) -> bool {
        self.recursive_anchors.borrow().get(base).copied().unwrap_or(false)
    }

    pub fn dynamic_anchor(&self, base: &str, name: &str) -> Option<AnchorTarget> {
        let anchors = self.anchors.borrow();
        anchors
            .get(base)
            .and_then(|m| m.get(name))
            .filter(|t| t.dynamic)
            .cloned()
    }

    /// Resolve a reference string against a base URI.
    pub fn resolve(&self, base: &str, reference: &str, current_draft: Draft) -> Result<Resolved, RefError> {
        let parsed = uri::parse(reference)
            .map_err(|e| RefError(format!("Invalid URI reference '{}': {}", reference, e)))?;
        let base_uri = match uri::parse(base) {
            Ok(b) => b,
            Err(_) => UriRef {
                scheme: None,
                authority: None,
                path: String::new(),
                query: None,
                fragment: None,
            },
        };
        let mut resolved = uri::resolve(&base_uri, &parsed);
        uri::normalize(&mut resolved);
        let fragment = resolved.fragment.clone().unwrap_or_default();
        let target_base = resolved.to_string_no_fragment();
        let resource = match self.get_resource(&target_base) {
            Some(r) => r,
            None => {
                self.retrieve(&target_base, &resolved, current_draft)?;
                self.get_resource(&target_base).ok_or_else(|| {
                    RefError(format!(
                        "Resource '{}' is not present in a registry and retrieving it failed",
                        target_base
                    ))
                })?
            }
        };
        if fragment.is_empty() {
            return Ok(Resolved {
                value: resource.value.clone(),
                base: resource.base.clone(),
                draft: resource.draft,
                pointer: String::new(),
                doc: resource.doc.clone(),
            });
        }
        if fragment.starts_with('/') {
            let decoded = uri::percent_decode(&fragment);
            let target = lookup_pointer(&resource.value, &decoded)?;
            Ok(Resolved {
                value: Rc::new(target.clone()),
                base: resource.base.clone(),
                draft: resource.draft,
                pointer: decoded,
                doc: resource.doc.clone(),
            })
        } else {
            let decoded = uri::percent_decode(&fragment);
            let anchors = self.anchors.borrow();
            let target = anchors
                .get(&target_base)
                .and_then(|m| m.get(&decoded))
                .cloned()
                .ok_or_else(|| RefError(format!("Anchor '{}' does not exist", decoded)))?;
            Ok(Resolved {
                value: target.value.clone(),
                base: resource.base.clone(),
                draft: resource.draft,
                pointer: String::new(),
                doc: resource.doc.clone(),
            })
        }
    }

    fn retrieve(&self, target_base: &str, uri: &UriRef, current_draft: Draft) -> Result<(), RefError> {
        let fail = |msg: String| {
            RefError(format!(
                "Resource '{}' is not present in a registry and retrieving it failed: {}",
                target_base, msg
            ))
        };
        let scheme = uri.scheme.clone().unwrap_or_default();
        let bytes: Vec<u8> = match scheme.as_str() {
            "file" => {
                let path = uri::percent_decode(&uri.path);
                std::fs::read(&path).map_err(|e| fail(e.to_string()))?
            }
            "http" => crate::fetch::http_get(uri, &self.fetch).map_err(|e| fail(e))?,
            "https" => {
                return Err(fail(format!("error sending request for url ({})", target_base)));
            }
            other => return Err(fail(format!("Unknown scheme {}", other))),
        };
        let value: Value = serde_json::from_slice(&bytes).map_err(|e| {
            if scheme == "file" {
                fail(e.to_string())
            } else {
                fail(format!("error decoding response body for url ({})", target_base))
            }
        })?;
        let draft = Draft::detect(&value, current_draft).unwrap_or(current_draft);
        let doc = Rc::new(value);
        self.add_document(target_base, doc, draft)
    }
}

/// Look up a JSON pointer, with the quirk that descending into a scalar
/// returns the scalar itself.
pub fn lookup_pointer<'a>(root: &'a Value, pointer: &str) -> Result<&'a Value, RefError> {
    let mut current = root;
    if pointer.is_empty() {
        return Ok(current);
    }
    for token in pointer[1..].split('/') {
        let token = unescape_pointer(token);
        match current {
            Value::Object(map) => {
                current = map
                    .get(&token)
                    .ok_or_else(|| RefError(format!("Pointer '{}' does not exist", pointer)))?;
            }
            Value::Array(arr) => {
                let idx: usize = if token.len() > 1 && token.starts_with('0') {
                    return Err(RefError(format!("Pointer '{}' does not exist", pointer)));
                } else {
                    token.parse().map_err(|_| {
                        RefError(format!(
                            "Failed to parse array index '{}' in pointer '{}'",
                            token, pointer
                        ))
                    })?
                };
                current = arr
                    .get(idx)
                    .ok_or_else(|| RefError(format!("Pointer '{}' does not exist", pointer)))?;
            }
            _ => return Ok(current),
        }
    }
    Ok(current)
}
