    pub doc: Rc<Value>,
    pub pointer: String,
}

#[derive(Clone)]
pub struct AnchorTarget {
    pub value: Rc<Value>,
    pub pointer: String,
    pub dynamic: bool,
}

pub struct FetchConfig {
