    /// Register the built-in meta-schemas.
    pub fn add_meta_schemas(&self) -> Result<(), RefError> {
        for draft in Draft::all() {
            for (uri, text) in draft.meta_schemas() {
                let value: Value = serde_json::from_str(text).expect("valid meta-schema");
                let doc = Rc::new(value);
                self.add_document(uri, doc, draft)?;
