    }

    fn register(
        &self,
        base: &str,
        value: Rc<Value>,
        doc: Rc<Value>,
        draft: Draft,
        pointer: String,
    ) -> Result<(), RefError> {
        let res = Resource {
            value: value.clone(),
            base: base.to_string(),
