                }
            }
        }
        self.scan(base, &value, doc, draft, &pointer)
    }

    fn add_anchor(&self, base: &str, name: &str, target: AnchorTarget) {
        let mut anchors = self.anchors.borrow_mut();
        let m = anchors.entry(base.to_string()).or_default();
        m.entry(name.to_string()).or_insert(target);
    }

    /// Recursively scan a schema for embedded resources and anchors.
    fn scan(
        &self,
        base: &str,
        schema: &Rc<Value>,
        doc: Rc<Value>,
        draft: Draft,
        pointer: &str,
    ) -> Result<(), RefError> {
        let obj = match schema.as_object() {
            Some(o) => o,
            None => return Ok(()),
        };
        // anchors declared on this schema object
        if matches!(draft, Draft::Draft201909 | Draft::Draft202012) {
            if let Some(Value::String(a)) = obj.get("$anchor") {
                self.add_anchor(
                    base,
                    a,
                    AnchorTarget {
                        value: schema.clone(),
                        pointer: pointer.to_string(),
                        dynamic: false,
                    },
