            }
            if draft == Draft::Draft202012 {
                if let Some(Value::String(a)) = obj.get("$dynamicAnchor") {
                    self.add_anchor(
                        base,
                        a,
                        AnchorTarget {
                            value: schema.clone(),
                            pointer: pointer.to_string(),
                            dynamic: true,
