                    let mut resolved = uri::resolve(&base_uri, &parsed);
                    uri::normalize(&mut resolved);
                    let frag = resolved.fragment.clone();
                    let no_frag = resolved.to_string_no_fragment();
                    let is_plain_anchor = frag.as_ref().map_or(false, |f| !f.is_empty() && !f.starts_with('/'));
                    if is_plain_anchor && draft.ref_ignores_siblings() {
                        // `$id: "#foo"` style plain-name fragment anchor.
                        if no_frag == base || parsed.scheme.is_none() && parsed.authority.is_none() && parsed.path.is_empty() && parsed.query.is_none() {
                            self.add_anchor(
