                        if no_frag != base {
                            new_base = Some(no_frag);
                        }
                    }
                }
            }
            match new_base {
                Some(nb) => {
                    self.register(&nb, sub_rc, doc.clone(), sub_draft, sub_ptr)?;
                }
                None => {
                    self.scan(base, &sub_rc, doc.clone(), sub_draft, &sub_ptr)?;
                }
            }
        }
        Ok(())
    }

    pub fn has_resource(&self, base: &str) -> bool {
        self.resources.borrow().contains_key(base)
    }

    pub fn get_resource(&self, base: &str) -> Option<Resource> {
        self.resources.borrow().get(base).cloned()
    }

    pub fn has_recursive_anchor(&self, base: &str) -> bool {
        self.recursive_anchors.borrow().get(base).copied().unwrap_or(false)
    }

    pub fn dynamic_anchor(&self, base: &str, name: &str) -> Option<AnchorTarget> {
        let anchors = self.anchors.borrow();
        anchors
            .get(base)
            .and_then(|m| m.get(name))
            .filter(|t| t.dynamic)
            .cloned()
    }

    /// Resolve a reference string against a base URI.
    pub fn resolve(&self, base: &str, reference: &str, current_draft: Draft) -> Result<Resolved, RefError> {
        let parsed = uri::parse(reference)
            .map_err(|e| RefError(format!("Invalid URI reference '{}': {}", reference, e)))?;
        let base_uri = match uri::parse(base) {
            Ok(b) => b,
            Err(_) => UriRef {
                scheme: None,
                authority: None,
