                value: resource.value.clone(),
                base: resource.base.clone(),
                draft: resource.draft,
                pointer: String::new(),
                doc: resource.doc.clone(),
            });
        }
        if fragment.starts_with('/') {
            let decoded = uri::percent_decode(&fragment);
            let target = lookup_pointer(&resource.value, &decoded)?;
            Ok(Resolved {
                value: Rc::new(target.clone()),
                base: resource.base.clone(),
                draft: resource.draft,
                pointer: decoded,
                doc: resource.doc.clone(),
            })
        } else {
            let decoded = uri::percent_decode(&fragment);
            let anchors = self.anchors.borrow();
            let target = anchors
                .get(&target_base)
                .and_then(|m| m.get(&decoded))
                .cloned()
                .ok_or_else(|| RefError(format!("Anchor '{}' does not exist", decoded)))?;
            Ok(Resolved {
                value: target.value.clone(),
                base: resource.base.clone(),
                draft: resource.draft,
                pointer: String::new(),
                doc: resource.doc.clone(),
            })
        }
    }

    fn retrieve(&self, target_base: &str, uri: &UriRef, current_draft: Draft) -> Result<(), RefError> {
        let fail = |msg: String| {
            RefError(format!(
                "Resource '{}' is not present in a registry and retrieving it failed: {}",
                target_base, msg
            ))
        };
        let scheme = uri.scheme.clone().unwrap_or_default();
        let bytes: Vec<u8> = match scheme.as_str() {
            "file" => {
                let path = uri::percent_decode(&uri.path);
                std::fs::read(&path).map_err(|e| fail(e.to_string()))?
            }
            "http" => crate::fetch::http_get(uri, &self.fetch).map_err(|e| fail(e))?,
            "https" => {
                return Err(fail(format!("error sending request for url ({})", target_base)));
            }
            other => return Err(fail(format!("Unknown scheme {}", other))),
        };
        let value: Value = serde_json::from_slice(&bytes).map_err(|e| {
            if scheme == "file" {
                fail(e.to_string())
            } else {
                fail(format!("error decoding response body for url ({})", target_base))
            }
        })?;
        let draft = Draft::detect(&value, current_draft).unwrap_or(current_draft);
        let doc = Rc::new(value);
        self.add_document(target_base, doc, draft)
    }
}

/// Look up a JSON pointer, with the quirk that descending into a scalar
/// returns the scalar itself.
pub fn lookup_pointer<'a>(root: &'a Value, pointer: &str) -> Result<&'a Value, RefError> {
    let mut current = root;
    if pointer.is_empty() {
        return Ok(current);
    }
    for token in pointer[1..].split('/') {
        let token = unescape_pointer(token);
        match current {
            Value::Object(map) => {
                current = map
                    .get(&token)
                    .ok_or_else(|| RefError(format!("Pointer '{}' does not exist", pointer)))?;
            }
            Value::Array(arr) => {
                let idx: usize = if token.len() > 1 && token.starts_with('0') {
                    return Err(RefError(format!("Pointer '{}' does not exist", pointer)));
                } else {
                    token.parse().map_err(|_| {
                        RefError(format!(
                            "Failed to parse array index '{}' in pointer '{}'",
                            token, pointer
                        ))
                    })?
                };
                current = arr
                    .get(idx)
                    .ok_or_else(|| RefError(format!("Pointer '{}' does not exist", pointer)))?;
            }
            _ => return Ok(current),
        }
    }
    Ok(current)
}
