//! Translation of ECMA 262 regular expressions into the syntax understood by
//! `fancy_regex`.

/// Translate ECMA-262 specific escapes into equivalent Rust regex syntax.
pub fn translate(pattern: &str) -> String {
    let chars: Vec<char> = pattern.chars().collect();
    let mut out = String::with_capacity(pattern.len() + 16);
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            let n = chars[i + 1];
            match n {
                'd' => {
                    out.push_str("[0-9]");
                    i += 2;
                }
                'D' => {
                    out.push_str("[^0-9]");
                    i += 2;
                }
                'w' => {
                    out.push_str("[A-Za-z0-9_]");
                    i += 2;
                }
                'W' => {
                    out.push_str("[^A-Za-z0-9_]");
                    i += 2;
                }
                's' => {
                    out.push_str("[ \t\n\r\u{0b}\u{0c}\u{a0}\u{feff}\u{2003}\u{2029}]");
                    i += 2;
                }
                'S' => {
                    out.push_str("[^ \t\n\r\u{0b}\u{0c}\u{a0}\u{feff}\u{2003}\u{2029}]");
                    i += 2;
                }
                'c' if i + 2 < chars.len() && chars[i + 2].is_ascii_alphabetic() => {
                    let code = (chars[i + 2] as u32) % 32;
                    let ch = char::from_u32(code).unwrap_or('\0');
                    match ch {
                        '\n' => out.push_str("\\n"),
                        '\r' => out.push_str("\\r"),
                        '\t' => out.push_str("\\t"),
                        _ => out.push_str(&format!("\\x{:02x}", code)),
                    }
                    i += 3;
                }
                _ => {
                    out.push(c);
                    out.push(n);
                    i += 2;
                }
            }
        } else {
            out.push(c);
            i += 1;
        }
    }
    out
}

pub fn compile(pattern: &str) -> Result<(fancy_regex::Regex, String), ()> {
    let translated = translate(pattern);
    match fancy_regex::Regex::new(&translated) {
        Ok(r) => Ok((r, translated)),
        Err(_) => Err(()),
    }
}

pub fn is_valid(pattern: &str) -> bool {
    compile(pattern).is_ok()
}
