{"command":"cat > /workspace/src/formats.rs <<'EOF'
//! Format validators.

use crate::draft::Draft;
use crate::uri;

pub fn is_known(name: &str, draft: Draft) -> bool {
    draft.supports_format(name)
}

/// Validate `value` against the named format. Unknown formats are valid.
pub fn check(name: &str, value: &str) -> bool {
    match name {
        "date" => is_date(value),
        "time" => is_time(value),
        "date-time" => is_date_time(value),
        "duration" => is_duration(value),
        "email" => is_email(value, false),
        "idn-email" => is_email(value, true),
        "hostname" => is_hostname(value),
        "idn-hostname" => is_idn_hostname(value),
        "ipv4" => value.parse::<std::net::Ipv4Addr>().is_ok(),
        "ipv6" => is_ipv6(value),
        "uri" => uri::parse(value).map(|u| u.scheme.is_some()).unwrap_or(false),
        "uri-reference" => uri::parse(value).is_ok(),
        "iri" => uri::parse_iri(value).map(|u| u.scheme.is_some()).unwrap_or(false),
        "iri-reference" => uri::parse_iri(value).is_ok(),
        "uuid" => is_uuid(value),
        "uri-template" => is_uri_template(value),
        "json-pointer" => is_json_pointer(value),
        "relative-json-pointer" => is_relative_json_pointer(value),
        "regex" => is_regex(value),
        _ => true,
    }
}

fn is_regex(value: &str) -> bool {
    let translated = crate::ecma::translate(value);
    fancy_regex::Expr::parse_tree(&translated).is_ok()
}

fn is_ipv6(value: &str) -> bool {
    if value.contains('%') {
        return false;
    }
    value.parse::<std::net::Ipv6Addr>().is_ok()
}

fn digits(s: &[u8]) -> bool {
    !s.is_empty() && s.iter().all(|b| b.is_ascii_digit())
}

fn num(s: &[u8]) -> u32 {
    s.iter().fold(0u32, |acc, b| acc * 10 + (b - b'0') as u32)
}

fn days_in_month(year: u32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

fn is_date(value: &str) -> bool {
    let b = value.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    if !digits(&b[0..4]) || !digits(&b[5..7]) || !digits(&b[8..10]) {
        return false;
    }
    let y = num(&b[0..4]);
    let m = num(&b[5..7]);
    let d = num(&b[8..10]);
    if !(1..=12).contains(&m) {
        return false;
    }
    d >= 1 && d <= days_in_month(y, m)
}

/// Parse an RFC 3339 full-time. Returns true if valid.
fn is_time(value: &str) -> bool {
    let b = value.as_bytes();
    // hh:mm:ss
    if b.len() < 9 || b[2] != b':' || b[5] != b':' {
        return false;
    }
    if !digits(&b[0..2]) || !digits(&b[3..5]) || !digits(&b[6..8]) {
        return false;
    }
    let h = num(&b[0..2]);
    let m = num(&b[3..5]);
    let s = num(&b[6..8]);
    if h > 23 || m > 59 || s > 60 {
        return false;
    }
    let mut i = 8;
    if i < b.len() && b[i] == b'.' {
        i += 1;
        let start = i;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        if i == start {
            return false;
        }
    }
    if i >= b.len() {
        return false;
    }
    let (oh, om, sign): (i32, i32, i32) = match b[i] {
        b'Z' | b'z' => {
            if i + 1 != b.len() {
                return false;
            }
            (0, 0, 1)
        }
        b'+' | b'-' => {
            let sign = if b[i] == b'+' { 1 } else { -1 };
            let rest = &b[i + 1..];
            if rest.len() != 5 || rest[2] != b':' || !digits(&rest[0..2]) || !digits(&rest[3..5]) {
                return false;
            }
            let oh = num(&rest[0..2]) as i32;
            let om = num(&rest[3..5]) as i32;
            if oh > 23 || om > 59 {
                return false;
            }
            (oh, om, sign)
        }
        _ => return false,
    };
    if s == 60 {
        // leap second: UTC time must be 23:59
        let total = h as i32 * 60 + m as i32 - sign * (oh * 60 + om);
        let total = ((total % 1440) + 1440) % 1440;
        return total == 23 * 60 + 59;
    }
    true
}

fn is_date_time(value: &str) -> bool {
    let b = value.as_bytes();
    if b.len() < 11 {
        return false;
    }
    if b[10] != b'T' && b[10] != b't' {
        return false;
    }
    is_date(&value[..10]) && is_time(&value[11..])
}

fn is_duration(value: &str) -> bool {
    let b = value.as_bytes();
    if b.len() < 2 || b[0] != b'P' {
        return false;
    }
    let rest = &value[1..];
    // Week form
    if rest.ends_with('W') {
        let d = &rest[..rest.len() - 1];
        return digits(d.as_bytes());
    }
    let (date_part, time_part) = match rest.find('T') {
        Some(p) => (&rest[..p], Some(&rest[p + 1..])),
        None => (rest, None),
    };
    fn parse_components(s: &str, order: &[u8]) -> Option<usize> {
        // returns number of components parsed, or None if invalid
        let b = s.as_bytes();
        let mut i = 0;
        let mut next_allowed = 0usize; // index into order
        let mut count = 0;
        while i < b.len() {
            let start = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            if i == start || i >= b.len() {
                return None;
            }
            let unit = b[i];
            let pos = order.iter().position(|&u| u == unit)?;
            if pos < next_allowed {
                return None;
            }
            next_allowed = pos + 1;
            count += 1;
            i += 1;
        }
        Some(count)
    }
    let date_count = match parse_components(date_part, b"YMD") {
        Some(c) => c,
        None => return false,
    };
    let time_count = match time_part {
        Some(t) => match parse_components(t, b"HMS") {
            Some(0) | None => return false,
            Some(c) => c,
        },
        None => 0,
    };
    date_count + time_count > 0
}

fn is_atext(c: char) -> bool {
    c.is_ascii_alphanumeric()
        || matches!(
            c,
            '!' | '#' | '$' | '%' | '&' | '\'' | '*' | '+' | '/' | '=' | '?' | '^' | '_' | '`' | '{' | '|' | '}' | '~' | '-'
        )
        || !c.is_ascii()
}

fn is_email(value: &str, idn: bool) -> bool {
    let at = match value.rfind('@') {
        Some(p) => p,
        None => return false,
    };
    let local = &value[..at];
    let domain = &value[at + 1..];
    if local.is_empty() || domain.is_empty() {
        return false;
    }
    if local.chars().count() > 64 {
        return false;
    }
    // local part
    if local.starts_with('"') && local.ends_with('"') && local.len() >= 2 {
        let inner = &local[1..local.len() - 1];
        let mut escaped = false;
        for c in inner.chars() {
            if escaped {
                escaped = false;
                continue;
            }
            if c == '\\' {
                escaped = true;
                continue;
            }
            if c == '"' || c == '\n' || c == '\r' {
                return false;
            }
        }
        if escaped {
            return false;
        }
    } else {
        if local.starts_with('.') || local.ends_with('.') || local.contains("..") {
            return false;
        }
        if !local.chars().all(|c| is_atext(c) || c == '.') {
            return false;
        }
        if local.chars().any(|c| c.is_whitespace()) {
            return false;
        }
    }
    // domain
    if domain.starts_with('[') && domain.ends_with(']') {
        let inner = &domain[1..domain.len() - 1];
        if let Some(v6) = inner.strip_prefix("IPv6:") {
            return is_ipv6(v6);
        }
        return inner.parse::<std::net::Ipv4Addr>().is_ok();
    }
    if idn {
        is_idn_hostname(domain)
    } else {
        is_hostname(domain)
    }
}

fn is_hostname(value: &str) -> bool {
    if value.is_empty() || value.len() > 253 {
        return false;
    }
    for label in value.split('.') {
        if label.is_empty() || label.len() > 63 {
            return false;
        }
        if label.starts_with('-') || label.ends_with('-') {
            return false;
        }
        if !label.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
            return false;
        }
    }
    true
}

fn is_idn_hostname(value: &str) -> bool {
    if value.is_empty() {
        return false;
    }
    if value.ends_with('.') {
        return false;
    }
    // Reject characters that are disallowed in IDNA 2008 but that UTS 46 maps or keeps.
    for c in value.chars() {
        if matches!(c, '\u{302E}' | '\u{302F}' | '\u{0640}') {
            return false;
        }
    }
    // Contextual rules applied per label (before mapping).
    for label in value.split('.') {
        if label.is_empty() {
            return false;
        }
        if !check_contextual_rules(label) {
            return false;
        }
    }
    let uts = idna::uts46::Uts46::new();
    let res = uts.to_ascii(
        value.as_bytes(),
        idna::uts46::AsciiDenyList::STD3,
        idna::uts46::Hyphens::Check,
        idna::uts46::DnsLength::Verify,
    );
    let ascii = match res {
        Ok(a) => a.to_string(),
        Err(_) => return false,
    };
    // Validate punycode labels decode to something and the result is a hostname.
    for label in ascii.split('.') {
        if label.is_empty() || label.len() > 63 {
            return false;
        }
        if let Some(rest) = label.strip_prefix("xn--") {
            match idna::punycode::decode_to_string(rest) {
                Some(decoded) => {
                    if decoded.is_empty() || decoded.is_ascii() {
                        return false;
                    }
                    if !check_contextual_rules(&decoded) {
                        return false;
                    }
                }
                None => return false,
            }
        }
    }
    true
}

fn is_greek(c: char) -> bool {
    let v = c as u32;
    (0x0370..=0x03FF).contains(&v) || (0x1F00..=0x1FFF).contains(&v)
}

fn is_hebrew(c: char) -> bool {
    let v = c as u32;
    (0x0590..=0x05FF).contains(&v)
}

fn is_hiragana_katakana_han(c: char) -> bool {
    let v = c as u32;
    (0x3041..=0x3096).contains(&v)
        || (0x309D..=0x309F).contains(&v)
        || (0x30A1..=0x30FA).contains(&v)
        || (0x30FC..=0x30FF).contains(&v)
        || (0x31F0..=0x31FF).contains(&v)
        || (0x2E80..=0x2FDF).contains(&v)
        || (0x3005..=0x3007).contains(&v)
        || (0x3021..=0x3029).contains(&v)
        || (0x3038..=0x303B).contains(&v)
        || (0x3400..=0x4DBF).contains(&v)
        || (0x4E00..=0x9FFF).contains(&v)
        || (0xF900..=0xFAFF).contains(&v)
        || (0xFF66..=0xFF9D).contains(&v)
        || (0x20000..=0x3134F).contains(&v)
}

fn check_contextual_rules(label: &str) -> bool {
    let chars: Vec<char> = label.chars().collect();
    let has_arabic_indic = chars.iter().any(|c| ('\u{0660}'..='\u{0669}').contains(c));
    let has_ext_arabic_indic = chars.iter().any(|c| ('\u{06F0}'..='\u{06F9}').contains(c));
    if has_arabic_indic && has_ext_arabic_indic {
        return false;
    }
    for (i, &c) in chars.iter().enumerate() {
        match c {
            '\u{00B7}' => {
                // MIDDLE DOT: between two 'l'
                if i == 0 || i + 1 >= chars.len() || chars[i - 1] != 'l' || chars[i + 1] != 'l' {
                    return false;
                }
            }
            '\u{0375}' => {
                // GREEK LOWER NUMERAL SIGN (KERAIA): followed by Greek
                if i + 1 >= chars.len() || !is_greek(chars[i + 1]) {
                    return false;
                }
            }
            '\u{05F3}' | '\u{05F4}' => {
                // HEBREW GERESH / GERSHAYIM: preceded by Hebrew
                if i == 0 || !is_hebrew(chars[i - 1]) {
                    return false;
                }
            }
            '\u{30FB}' => {
                // KATAKANA MIDDLE DOT: label must contain Hiragana/Katakana/Han
                if !chars.iter().any(|&x| is_hiragana_katakana_han(x)) {
                    return false;
                }
            }
            _ => {}
        }
    }
    true
}

fn is_uuid(value: &str) -> bool {
    let b = value.as_bytes();
    if b.len() != 36 {
        return false;
    }
    for (i, &c) in b.iter().enumerate() {
        if i == 8 || i == 13 || i == 18 || i == 23 {
            if c != b'-' {
                return false;
            }
        } else if !c.is_ascii_hexdigit() {
            return false;
        }
    }
    true
}

fn is_json_pointer(value: &str) -> bool {
    if value.is_empty() {
        return true;
    }
    if !value.starts_with('/') {
        return false;
    }
    let b = value.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'~' {
            if i + 1 >= b.len() || (b[i + 1] != b'0' && b[i + 1] != b'1') {
                return false;
            }
            i += 2;
        } else {
            i += 1;
        }
    }
    true
}

fn is_relative_json_pointer(value: &str) -> bool {
    let b = value.as_bytes();
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
    }
    if i == 0 {
        return false;
    }
    if i > 1 && b[0] == b'0' {
        return false;
    }
    if i == b.len() {
        return true;
    }
    if b[i] == b'#' {
        return i + 1 == b.len();
    }
    is_json_pointer(&value[i..])
}

fn is_uri_template(value: &str) -> bool {
    let chars: Vec<char> = value.chars().collect();
    let mut i = 0;
    fn is_literal(c: char) -> bool {
        let v = c as u32;
        v == 0x21
            || (0x23..=0x24).contains(&v)
            || v == 0x26
            || (0x28..=0x3B).contains(&v)
            || v == 0x3D
            || (0x3F..=0x5B).contains(&v)
            || v == 0x5D
            || v == 0x5F
            || (0x61..=0x7A).contains(&v)
            || v == 0x7E
            || uri::is_ucschar(c)
            || uri::is_iprivate(c)
    }
    fn pct(chars: &[char], i: usize) -> bool {
        i + 2 < chars.len() + 0 && chars.len() > i + 2 && chars[i] == '%' && chars[i + 1].is_ascii_hexdigit() && chars[i + 2].is_ascii_hexdigit()
    }
    while i < chars.len() {
        let c = chars[i];
        if c == '{' {
            i += 1;
            if i < chars.len() && matches!(chars[i], '+' | '#' | '.' | '/' | ';' | '?' | '&' | '=' | ',' | '!' | '@' | '|') {
                i += 1;
            }
            // variable-list
            loop {
                // varname
                let start = i;
                loop {
                    if i < chars.len() && (chars[i].is_ascii_alphanumeric() || chars[i] == '_') {
                        i += 1;
                    } else if pct(&chars, i) {
                        i += 3;
                    } else if i < chars.len() && chars[i] == '.' && i > start {
                        // dot must be followed by varchar
                        if i + 1 < chars.len() && (chars[i + 1].is_ascii_alphanumeric() || chars[i + 1] == '_' || pct(&chars, i + 1)) {
                            i += 1;
                        } else {
                            return false;
                        }
                    } else {
                        break;
                    }
                }
                if i == start {
                    return false;
                }
                // modifier
                if i < chars.len() && chars[i] == ':' {
                    i += 1;
                    let ds = i;
                    while i < chars.len() && chars[i].is_ascii_digit() {
                        i += 1;
                    }
                    let n = &chars[ds..i];
                    if n.is_empty() || n.len() > 4 || n[0] == '0' {
                        return false;
                    }
                } else if i < chars.len() && chars[i] == '*' {
                    i += 1;
                }
                if i < chars.len() && chars[i] == ',' {
                    i += 1;
                    continue;
                }
                break;
            }
            if i < chars.len() && chars[i] == '}' {
                i += 1;
            } else {
                return false;
            }
        } else if c == '%' {
            if pct(&chars, i) {
                i += 3;
            } else {
                return false;
            }
        } else if is_literal(c) {
            i += 1;
        } else {
            return false;
        }
    }
    true
}
