//! Compiled schema representation and the compiler.

use crate::draft::Draft;
use crate::ecma;
use crate::num::Num;
use crate::registry::{escape_pointer, RefError, Registry, Resolved};
use serde_json::{Map, Value};
use std::collections::{HashMap, HashSet};
use std::rc::Rc;

pub type NodeId = usize;

#[derive(Clone, Debug)]
pub struct Location {
    pub base: Rc<str>,
    pub pointer: String,
}

impl Location {
    pub fn child(&self, seg: &str) -> Location {
        Location {
            base: self.base.clone(),
            pointer: format!("{}/{}", self.pointer, escape_pointer(seg)),
        }
    }
    pub fn child_idx(&self, idx: usize) -> Location {
        Location {
            base: self.base.clone(),
            pointer: format!("{}/{}", self.pointer, idx),
        }
    }
    pub fn display(&self) -> String {
        format!("{}#{}", self.base, self.pointer)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum JsonType {
    Array,
    Boolean,
    Integer,
    Null,
    Number,
    Object,
    String,
}

impl JsonType {
    pub fn name(self) -> &'static str {
        match self {
            JsonType::Array => "array",
            JsonType::Boolean => "boolean",
            JsonType::Integer => "integer",
            JsonType::Null => "null",
            JsonType::Number => "number",
            JsonType::Object => "object",
            JsonType::String => "string",
        }
    }
    pub fn parse(s: &str) -> Option<JsonType> {
        Some(match s {
            "array" => JsonType::Array,
            "boolean" => JsonType::Boolean,
            "integer" => JsonType::Integer,
            "null" => JsonType::Null,
            "number" => JsonType::Number,
            "object" => JsonType::Object,
            "string" => JsonType::String,
            _ => return None,
        })
    }
    pub fn matches(self, v: &Value) -> bool {
        match self {
            JsonType::Array => v.is_array(),
            JsonType::Boolean => v.is_boolean(),
            JsonType::Null => v.is_null(),
            JsonType::Number => v.is_number(),
            JsonType::Object => v.is_object(),
            JsonType::String => v.is_string(),
            JsonType::Integer => match v {
                Value::Number(n) => Num::from_json(n).is_integer(),
                _ => false,
            },
        }
    }
}

#[derive(Clone, Debug)]
pub enum Sub {
    False,
    Node(NodeId),
}

#[derive(Clone, Debug)]
pub enum Dep {
    Required(Vec<String>),
    Schema(NodeId),
}

#[derive(Debug)]
pub enum Kind {
    /// A schema object: keyword children + annotation keywords.
    Schema { children: Vec<NodeId>, annotations: Map<String, Value> },
    False,
    Type(Vec<JsonType>),
    Const(Value),
    Enum(Vec<Value>),
    Minimum(Num),
    Maximum(Num),
    ExclusiveMinimum(Num),
    ExclusiveMaximum(Num),
    /// draft 4 style: minimum with exclusiveMinimum: true
    Minimum4Exclusive(Num),
    Maximum4Exclusive(Num),
    MultipleOf(Num),
    MinLength(u64),
    MaxLength(u64),
    MinItems(u64),
    MaxItems(u64),
    MinProperties(u64),
    MaxProperties(u64),
    Required(Vec<String>),
    Pattern { regex: fancy_regex::Regex, display: String },
    Format(String),
    UniqueItems,
    Content { encoding: Option<String>, media_type: Option<String> },
    Properties(Vec<(String, NodeId)>),
    PatternProperties(Vec<(String, fancy_regex::Regex, NodeId)>),
    AdditionalProperties {
        properties: Vec<(String, NodeId)>,
        patterns: Vec<(String, fancy_regex::Regex, NodeId)>,
        additional: Sub,
    },
    PropertyNames(NodeId),
    Items(NodeId),
    ItemsType(Vec<JsonType>),
    ItemsArray(Vec<NodeId>),
    AdditionalItems { prefix_len: usize, schema: Sub },
    PrefixItems(Vec<NodeId>),
    Contains { node: NodeId, min: Option<u64>, max: Option<u64> },
    DependentRequired(Vec<(String, Vec<String>)>),
    DependentSchemas(Vec<(String, NodeId)>),
    Dependencies(Vec<(String, Dep)>),
    AllOf(Vec<NodeId>),
    AnyOf(Vec<NodeId>),
    OneOf(Vec<NodeId>),
    Not { node: NodeId, schema: Value },
    IfThenElse { cond: NodeId, then: Option<NodeId>, otherwise: Option<NodeId> },
    UnevaluatedProperties { schema: Sub, parent: NodeId },
    UnevaluatedItems { schema: Sub, parent: NodeId },
    Ref { target: NodeId, lazy: bool },
    /// Dynamic reference: resolved at runtime using the dynamic scope.
    DynamicRef { anchor: Option<String>, fallback: NodeId, lazy: bool, candidates: Vec<(String, NodeId)> },
    RecursiveRef { fallback: NodeId, lazy: bool, candidates: Vec<(String, NodeId)> },
}

#[derive(Debug)]
pub struct Node {
    pub kind: Kind,
    pub location: Location,
    pub keyword: String,
    /// Base URI of the resource this node belongs to (for dynamic scope).
    pub base: Rc<str>,
    pub draft: Draft,
}

pub struct Compiled {
    pub nodes: Vec<Node>,
    pub root: NodeId,
}

#[derive(Clone, Debug)]
pub struct CompileError(pub String);

impl From<RefError> for CompileError {
    fn from(e: RefError) -> Self {
        CompileError(e.0)
    }
}

impl std::fmt::Display for CompileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

pub struct Compiler<'r> {
    pub registry: &'r Registry,
    pub nodes: Vec<Node>,
    pub assert_formats: bool,
    /// compile cache: (base, pointer-or-anchor key, draft) -> node
    cache: HashMap<String, NodeId>,
    in_progress: Vec<String>,
    /// nodes created for dynamic anchor candidates: anchor name -> list of (base, node)
    dynamic_targets: HashMap<String, Vec<(String, NodeId)>>,
    recursive_targets: Vec<(String, NodeId)>,
}

fn type_error(v: &Value, types: &[&str]) -> CompileError {
    if types.len() == 1 {
        CompileError(format!("{} is not of type \"{}\"", v, types[0]))
    } else {
        let list: Vec<String> = types.iter().map(|t| format!("\"{}\"", t)).collect();
        CompileError(format!("{} is not of types {}", v, list.join(", ")))
    }
}

const KEYWORD_ORDER: &[&str] = &[
    "type",
    "const",
    "enum",
    "minimum",
    "maximum",
    "exclusiveMinimum",
    "exclusiveMaximum",
    "multipleOf",
    "minLength",
    "maxLength",
    "minItems",
    "maxItems",
    "minProperties",
    "maxProperties",
    "required",
    "dependentRequired",
    "pattern",
    "format",
    "contentMediaType",
    "uniqueItems",
    "additionalProperties",
    "propertyNames",
    "items",
    "additionalItems",
    "prefixItems",
    "contains",
    "dependencies",
    "dependentSchemas",
    "allOf",
    "anyOf",
    "oneOf",
    "not",
    "if",
    "unevaluatedProperties",
    "unevaluatedItems",
    "$ref",
    "$recursiveRef",
    "$dynamicRef",
];

impl<'r> Compiler<'r> {
    pub fn new(registry: &'r Registry, assert_formats: bool) -> Compiler<'r> {
        Compiler {
            registry,
            nodes: Vec::new(),
            assert_formats,
            cache: HashMap::new(),
            in_progress: Vec::new(),
            dynamic_targets: HashMap::new(),
            recursive_targets: Vec::new(),
        }
    }

    fn push(&mut self, kind: Kind, location: Location, keyword: &str, base: &Rc<str>, draft: Draft) -> NodeId {
        self.nodes.push(Node {
            kind,
            location,
            keyword: keyword.to_string(),
            base: base.clone(),
            draft,
        });
        self.nodes.len() - 1
    }

    /// Compile a root schema. `base` is the resource URI (no fragment).
    pub fn compile_root(&mut self, schema: &Value, base: &str, draft: Draft) -> Result<NodeId, CompileError> {
        let base_rc: Rc<str> = Rc::from(base);
        let loc = Location {
            base: base_rc.clone(),
            pointer: String::new(),
        };
        let key = format!("{}#{}", base, "");
        self.compile_cached(schema, loc, base_rc, draft, key)
    }

    fn compile_cached(
        &mut self,
        schema: &Value,
        loc: Location,
        base: Rc<str>,
        draft: Draft,
        key: String,
    ) -> Result<NodeId, CompileError> {
        if let Some(&id) = self.cache.get(&key) {
            return Ok(id);
        }
        // Reserve a placeholder so that recursive references can point at it.
        let placeholder = self.push(
            Kind::Schema {
                children: Vec::new(),
                annotations: Map::new(),
            },
            loc.clone(),
            "",
            &base,
            draft,
        );
        self.cache.insert(key.clone(), placeholder);
        self.in_progress.push(key.clone());
        let result = self.compile_schema_into(placeholder, schema, loc, base, draft);
        self.in_progress.pop();
        result?;
        Ok(placeholder)
    }

    fn compile_schema_into(
        &mut self,
        id: NodeId,
        schema: &Value,
        loc: Location,
        base: Rc<str>,
        draft: Draft,
    ) -> Result<(), CompileError> {
        match schema {
            Value::Bool(true) => {
                self.nodes[id].kind = Kind::Schema {
                    children: Vec::new(),
                    annotations: Map::new(),
                };
                Ok(())
            }
            Value::Bool(false) => {
                self.nodes[id].kind = Kind::False;
                Ok(())
            }
            Value::Object(obj) => {
                let (children, annotations) = self.compile_object(id, obj, &loc, &base, draft)?;
                self.nodes[id].kind = Kind::Schema {
                    children,
                    annotations,
                };
                Ok(())
            }
            other => Err(type_error(other, &["boolean", "object"])),
        }
    }

    /// Compile a subschema value located at `loc`.
    fn compile_sub(&mut self, schema: &Value, loc: Location, base: Rc<str>, draft: Draft) -> Result<NodeId, CompileError> {
        match schema {
            Value::Bool(_) | Value::Object(_) => {}
            other => return Err(type_error(other, &["boolean", "object"])),
        }
        // Determine whether this subschema changes the base URI.
        let (base, draft) = self.sub_base(schema, &base, draft)?;
        let key = format!("{}#{}", base, loc.pointer);
        self.compile_cached(schema, loc, base, draft, key)
    }

    fn sub_base(&self, schema: &Value, base: &Rc<str>, draft: Draft) -> Result<(Rc<str>, Draft), CompileError> {
        let mut new_base = base.clone();
        let mut new_draft = draft;
        if let Some(obj) = schema.as_object() {
            if matches!(draft, Draft::Draft201909 | Draft::Draft202012) {
                if let Some(Value::String(s)) = obj.get("$schema") {
                    if let Some(d) = Draft::from_schema_uri(s) {
                        new_draft = d;
                    }
                }
            }
            if let Some(Value::String(id)) = obj.get(draft.id_keyword()) {
                let parsed = crate::uri::parse(id)
                    .map_err(|e| CompileError(format!("Invalid URI reference '{}': {}", id, e)))?;
                let base_uri = crate::uri::parse(base).unwrap_or(crate::uri::UriRef {
                    scheme: None,
                    authority: None,
                    path: String::new(),
                    query: None,
                    fragment: None,
                });
                let mut resolved = crate::uri::resolve(&base_uri, &parsed);
                crate::uri::normalize(&mut resolved);
                let no_frag = resolved.to_string_no_fragment();
                if no_frag.as_str() != &**base {
                    new_base = Rc::from(no_frag.as_str());
                }
            }
        }
        Ok((new_base, new_draft))
    }

    fn compile_object(
        &mut self,
        self_id: NodeId,
        obj: &Map<String, Value>,
        loc: &Location,
        base: &Rc<str>,
        draft: Draft,
    ) -> Result<(Vec<NodeId>, Map<String, Value>), CompileError> {
        let mut children = Vec::new();
        let mut annotations = Map::new();

        // Draft <= 7: `$ref` overrides all siblings.
        if draft.ref_ignores_siblings() {
            if let Some(r) = obj.get("$ref") {
                for (k, v) in obj {
                    if k != "$ref" {
                        annotations.insert(k.clone(), v.clone());
                    }
                }
                if let Some(id) = self.compile_ref(r, loc, base, draft, self_id)? {
                    children.push(id);
                }
                return Ok((children, annotations));
            }
        }

        for (k, v) in obj {
            if !draft.is_known_keyword(k) {
                annotations.insert(k.clone(), v.clone());
            }
        }

        let has = |k: &str| obj.contains_key(k);
        for &kw in KEYWORD_ORDER {
            if !has(kw) {
                // special combos
                match kw {
                    "additionalProperties" => {
                        // handled below when absent: properties/patternProperties separately
                        if has("properties") && draft.is_known_keyword("properties") {
                            let id = self.compile_properties(obj.get("properties").unwrap(), loc, base, draft)?;
                            children.push(id);
                        }
                        if has("patternProperties") {
                            let id = self.compile_pattern_properties(obj.get("patternProperties").unwrap(), loc, base, draft)?;
                            children.push(id);
                        }
                    }
                    "contentMediaType" => {
                        if has("contentEncoding") && matches!(draft, Draft::Draft6 | Draft::Draft7) {
                            if let Some(id) = self.compile_content(obj, loc, base, draft) {
                                children.push(id);
                            }
                        }
                    }
                    "if" => {}
                    _ => {}
                }
                continue;
            }
            if !draft.is_known_keyword(kw) {
                continue;
            }
            let v = obj.get(kw).unwrap();
            let kloc = loc.child(kw);
            let node = match kw {
                "type" => {
                    let types = parse_types(v)?;
                    Some(self.push(Kind::Type(types), kloc, kw, base, draft))
                }
                "const" => Some(self.push(Kind::Const(v.clone()), kloc, kw, base, draft)),
                "enum" => match v {
                    Value::Array(items) => Some(self.push(Kind::Enum(items.clone()), kloc, kw, base, draft)),
                    other => return Err(type_error(other, &["array"])),
                },
                "minimum" | "maximum" | "exclusiveMinimum" | "exclusiveMaximum" => {
                    if draft == Draft::Draft4 && (kw == "exclusiveMinimum" || kw == "exclusiveMaximum") {
                        // handled with minimum/maximum
                        None
                    } else {
                        let n = match v {
                            Value::Number(n) => Num::from_json(n),
                            other => return Err(type_error(other, &["number"])),
                        };
                        let kind = match kw {
                            "minimum" => {
                                if draft == Draft::Draft4 && obj.get("exclusiveMinimum") == Some(&Value::Bool(true)) {
                                    Kind::Minimum4Exclusive(n)
                                } else {
                                    Kind::Minimum(n)
                                }
                            }
                            "maximum" => {
                                if draft == Draft::Draft4 && obj.get("exclusiveMaximum") == Some(&Value::Bool(true)) {
                                    Kind::Maximum4Exclusive(n)
                                } else {
                                    Kind::Maximum(n)
                                }
                            }
                            "exclusiveMinimum" => Kind::ExclusiveMinimum(n),
                            _ => Kind::ExclusiveMaximum(n),
                        };
                        Some(self.push(kind, kloc, kw, base, draft))
                    }
                }
                "multipleOf" => {
                    let n = match v {
                        Value::Number(n) => Num::from_json(n),
                        other => return Err(type_error(other, &["number"])),
                    };
                    Some(self.push(Kind::MultipleOf(n), kloc, kw, base, draft))
                }
                "minLength" | "maxLength" | "minItems" | "maxItems" | "minProperties" | "maxProperties" => {
                    let n = parse_non_negative(v)?;
                    let kind = match kw {
                        "minLength" => Kind::MinLength(n),
                        "maxLength" => Kind::MaxLength(n),
                        "minItems" => Kind::MinItems(n),
                        "maxItems" => Kind::MaxItems(n),
                        "minProperties" => Kind::MinProperties(n),
                        _ => Kind::MaxProperties(n),
                    };
                    Some(self.push(kind, kloc, kw, base, draft))
                }
                "required" => {
                    let names = parse_string_array(v)?;
                    Some(self.push(Kind::Required(names), kloc, kw, base, draft))
                }
                "dependentRequired" => {
                    let m = match v {
                        Value::Object(m) => m,
                        other => return Err(type_error(other, &["object"])),
                    };
                    let mut deps = Vec::new();
                    for (k, dv) in m {
                        deps.push((k.clone(), parse_string_array(dv)?));
                    }
                    Some(self.push(Kind::DependentRequired(deps), kloc, kw, base, draft))
                }
                "pattern" => {
                    let s = match v {
                        Value::String(s) => s,
                        other => return Err(type_error(other, &["string"])),
                    };
                    let (regex, display) = ecma::compile(s)
                        .map_err(|_| CompileError(format!("{} is not a \"regex\"", v)))?;
                    Some(self.push(Kind::Pattern { regex, display }, kloc, kw, base, draft))
                }
                "format" => {
                    if !self.assert_formats {
                        None
                    } else {
                        match v {
                            Value::String(s) if crate::formats::is_known(s, draft) => {
                                Some(self.push(Kind::Format(s.clone()), kloc, kw, base, draft))
                            }
                            _ => None,
                        }
                    }
                }
                "contentMediaType" => {
                    if matches!(draft, Draft::Draft6 | Draft::Draft7) {
                        self.compile_content(obj, loc, base, draft)
                    } else {
                        None
                    }
                }
                "uniqueItems" => match v {
                    Value::Bool(true) => Some(self.push(Kind::UniqueItems, kloc, kw, base, draft)),
                    _ => None,
                },
                "additionalProperties" => {
                    let properties = match obj.get("properties") {
                        Some(p) => self.compile_properties_map(p, loc, base, draft)?,
                        None => Vec::new(),
                    };
                    let patterns = match obj.get("patternProperties") {
                        Some(p) => self.compile_pattern_map(p, loc, base, draft)?,
                        None => Vec::new(),
                    };
                    match v {
                        Value::Bool(true) => {
                            // Equivalent to no additionalProperties.
                            if has("properties") {
                                let id = self.compile_properties(obj.get("properties").unwrap(), loc, base, draft)?;
                                children.push(id);
                            }
                            if has("patternProperties") {
                                let id = self.compile_pattern_properties(obj.get("patternProperties").unwrap(), loc, base, draft)?;
                                children.push(id);
                            }
                            None
                        }
                        Value::Bool(false) => Some(self.push(
                            Kind::AdditionalProperties {
                                properties,
                                patterns,
                                additional: Sub::False,
                            },
                            kloc,
                            kw,
                            base,
                            draft,
                        )),
                        Value::Object(_) => {
                            let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                            Some(self.push(
                                Kind::AdditionalProperties {
                                    properties,
                                    patterns,
                                    additional: Sub::Node(sub),
                                },
                                kloc,
                                kw,
                                base,
                                draft,
                            ))
                        }
                        other => return Err(type_error(other, &["boolean", "object"])),
                    }
                }
                "propertyNames" => match v {
                    Value::Bool(true) => None,
                    Value::Bool(false) | Value::Object(_) => {
                        let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                        Some(self.push(Kind::PropertyNames(sub), kloc, kw, base, draft))
                    }
                    _ => None,
                },
                "items" => match v {
                    Value::Bool(true) => None,
                    Value::Array(arr) => {
                        let mut subs = Vec::new();
                        for (i, item) in arr.iter().enumerate() {
                            subs.push(self.compile_sub(item, kloc.child_idx(i), base.clone(), draft)?);
                        }
                        Some(self.push(Kind::ItemsArray(subs), kloc, kw, base, draft))
                    }
                    Value::Bool(false) => {
                        let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                        Some(self.push(Kind::Items(sub), kloc, kw, base, draft))
                    }
                    Value::Object(m) => {
                        if m.len() == 1 && m.contains_key("type") && draft == Draft::Draft202012 || (m.len() == 1 && m.contains_key("type") && !has("additionalItems")) {
                            if let Some(Value::String(_)) = m.get("type") {
                                let types = parse_types(m.get("type").unwrap())?;
                                Some(self.push(Kind::ItemsType(types), kloc, kw, base, draft))
                            } else {
                                let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                                Some(self.push(Kind::Items(sub), kloc, kw, base, draft))
                            }
                        } else {
                            let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                            Some(self.push(Kind::Items(sub), kloc, kw, base, draft))
                        }
                    }
                    _ => None,
                },
                "additionalItems" => {
                    match obj.get("items") {
                        Some(Value::Array(arr)) => match v {
                            Value::Bool(true) => None,
                            Value::Bool(false) => Some(self.push(
                                Kind::AdditionalItems {
                                    prefix_len: arr.len(),
                                    schema: Sub::False,
                                },
                                kloc,
                                kw,
                                base,
                                draft,
                            )),
                            Value::Object(_) => {
                                let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                                Some(self.push(
                                    Kind::AdditionalItems {
                                        prefix_len: arr.len(),
                                        schema: Sub::Node(sub),
                                    },
                                    kloc,
                                    kw,
                                    base,
                                    draft,
                                ))
                            }
                            other => return Err(type_error(other, &["boolean", "object"])),
                        },
                        _ => None,
                    }
                }
                "prefixItems" => match v {
                    Value::Array(arr) => {
                        let mut subs = Vec::new();
                        for (i, item) in arr.iter().enumerate() {
                            subs.push(self.compile_sub(item, kloc.child_idx(i), base.clone(), draft)?);
                        }
                        Some(self.push(Kind::PrefixItems(subs), kloc, kw, base, draft))
                    }
                    other => return Err(type_error(other, &["array"])),
                },
                "contains" => {
                    let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                    let (min, max) = if matches!(draft, Draft::Draft201909 | Draft::Draft202012) {
                        let min = match obj.get("minContains") {
                            Some(Value::Number(n)) => parse_non_negative(&Value::Number(n.clone())).ok(),
                            _ => None,
                        };
                        let max = match obj.get("maxContains") {
                            Some(Value::Number(n)) => parse_non_negative(&Value::Number(n.clone())).ok(),
                            _ => None,
                        };
                        (min, max)
                    } else {
                        (None, None)
                    };
                    Some(self.push(Kind::Contains { node: sub, min, max }, kloc, kw, base, draft))
                }
                "dependencies" => {
                    let m = match v {
                        Value::Object(m) => m,
                        other => return Err(type_error(other, &["object"])),
                    };
                    let mut deps = Vec::new();
                    for (k, dv) in m {
                        match dv {
                            Value::Array(_) => deps.push((k.clone(), Dep::Required(parse_string_array(dv)?))),
                            Value::Bool(_) | Value::Object(_) => {
                                let sub = self.compile_sub(dv, kloc.child(k), base.clone(), draft)?;
                                deps.push((k.clone(), Dep::Schema(sub)));
                            }
                            other => return Err(type_error(other, &["boolean", "object"])),
                        }
                    }
                    Some(self.push(Kind::Dependencies(deps), kloc, kw, base, draft))
                }
                "dependentSchemas" => {
                    let m = match v {
                        Value::Object(m) => m,
                        other => return Err(type_error(other, &["object"])),
                    };
                    let mut deps = Vec::new();
                    for (k, dv) in m {
                        let sub = self.compile_sub(dv, kloc.child(k), base.clone(), draft)?;
                        deps.push((k.clone(), sub));
                    }
                    Some(self.push(Kind::DependentSchemas(deps), kloc, kw, base, draft))
                }
                "allOf" | "anyOf" | "oneOf" => {
                    let arr = match v {
                        Value::Array(a) => a,
                        other => return Err(type_error(other, &["array"])),
                    };
                    let mut subs = Vec::new();
                    for (i, item) in arr.iter().enumerate() {
                        subs.push(self.compile_sub(item, kloc.child_idx(i), base.clone(), draft)?);
                    }
                    let kind = match kw {
                        "allOf" => Kind::AllOf(subs),
                        "anyOf" => Kind::AnyOf(subs),
                        _ => Kind::OneOf(subs),
                    };
                    Some(self.push(kind, kloc, kw, base, draft))
                }
                "not" => {
                    let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                    Some(self.push(Kind::Not { node: sub, schema: v.clone() }, kloc, kw, base, draft))
                }
                "if" => {
                    let then = obj.get("then");
                    let otherwise = obj.get("else");
                    let valid_then = matches!(then, Some(Value::Bool(_)) | Some(Value::Object(_)));
                    let valid_else = matches!(otherwise, Some(Value::Bool(_)) | Some(Value::Object(_)));
                    if !(v.is_boolean() || v.is_object()) || (!valid_then && !valid_else) {
                        None
                    } else {
                        let cond = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                        let then_id = if valid_then {
                            Some(self.compile_sub(then.unwrap(), loc.child("then"), base.clone(), draft)?)
                        } else {
                            None
                        };
                        let else_id = if valid_else {
                            Some(self.compile_sub(otherwise.unwrap(), loc.child("else"), base.clone(), draft)?)
                        } else {
                            None
                        };
                        Some(self.push(
                            Kind::IfThenElse {
                                cond,
                                then: then_id,
                                otherwise: else_id,
                            },
                            kloc,
                            kw,
                            base,
                            draft,
                        ))
                    }
                }
                "unevaluatedProperties" | "unevaluatedItems" => match v {
                    Value::Bool(true) => None,
                    Value::Bool(false) => {
                        let kind = if kw == "unevaluatedProperties" {
                            Kind::UnevaluatedProperties { schema: Sub::False, parent: self_id }
                        } else {
                            Kind::UnevaluatedItems { schema: Sub::False, parent: self_id }
                        };
                        Some(self.push(kind, kloc, kw, base, draft))
                    }
                    Value::Object(_) => {
                        let sub = self.compile_sub(v, kloc.clone(), base.clone(), draft)?;
                        let kind = if kw == "unevaluatedProperties" {
                            Kind::UnevaluatedProperties { schema: Sub::Node(sub), parent: self_id }
                        } else {
                            Kind::UnevaluatedItems { schema: Sub::Node(sub), parent: self_id }
                        };
                        Some(self.push(kind, kloc, kw, base, draft))
                    }
                    other => return Err(type_error(other, &["boolean", "object"])),
                },
                "$ref" => self.compile_ref(v, loc, base, draft, self_id)?,
                "$recursiveRef" => {
                    if draft == Draft::Draft201909 {
                        self.compile_recursive_ref(v, loc, base, draft, self_id)?
                    } else {
                        None
                    }
                }
                "$dynamicRef" => {
                    if draft == Draft::Draft202012 {
                        self.compile_dynamic_ref(v, loc, base, draft, self_id)?
                    } else {
                        None
                    }
                }
                _ => None,
            };
            if let Some(id) = node {
                children.push(id);
            }
        }
        Ok((children, annotations))
    }

    fn compile_content(&mut self, obj: &Map<String, Value>, loc: &Location, base: &Rc<str>, draft: Draft) -> Option<NodeId> {
        let enc = obj.get("contentEncoding");
        let mt = obj.get("contentMediaType");
        let enc = match enc {
            Some(Value::String(s)) => Some(s.clone()),
            Some(_) => return None,
            None => None,
        };
        let mt = match mt {
            Some(Value::String(s)) => Some(s.clone()),
            Some(_) => return None,
            None => None,
        };
        let enc_known = enc.as_deref().map_or(true, |e| e == "base64");
        let mt_known = mt.as_deref().map_or(true, |m| m == "application/json");
        if !enc_known || !mt_known {
            return None;
        }
        if enc.is_none() && mt.is_none() {
            return None;
        }
        let kw = if mt.is_some() { "contentMediaType" } else { "contentEncoding" };
        let kloc = loc.child(kw);
        Some(self.push(
            Kind::Content {
                encoding: enc,
                media_type: mt,
            },
            kloc,
            kw,
            base,
            draft,
        ))
    }

    fn compile_properties_map(&mut self, v: &Value, loc: &Location, base: &Rc<str>, draft: Draft) -> Result<Vec<(String, NodeId)>, CompileError> {
        let m = match v {
            Value::Object(m) => m,
            other => return Err(type_error(other, &["object"])),
        };
        let ploc = loc.child("properties");
        let mut out = Vec::new();
        for (k, sv) in m {
            let sub = self.compile_sub(sv, ploc.child(k), base.clone(), draft)?;
            out.push((k.clone(), sub));
        }
        Ok(out)
    }

    fn compile_properties(&mut self, v: &Value, loc: &Location, base: &Rc<str>, draft: Draft) -> Result<NodeId, CompileError> {
        let props = self.compile_properties_map(v, loc, base, draft)?;
        Ok(self.push(Kind::Properties(props), loc.child("properties"), "properties", base, draft))
    }

    fn compile_pattern_map(&mut self, v: &Value, loc: &Location, base: &Rc<str>, draft: Draft) -> Result<Vec<(String, fancy_regex::Regex, NodeId)>, CompileError> {
        let m = match v {
            Value::Object(m) => m,
            other => return Err(type_error(other, &["object"])),
        };
        let ploc = loc.child("patternProperties");
        let mut out = Vec::new();
        for (k, sv) in m {
            let (regex, _) = ecma::compile(k).map_err(|_| CompileError(format!("{} is not a \"regex\"", sv)))?;
            let sub = self.compile_sub(sv, ploc.child(k), base.clone(), draft)?;
            out.push((k.clone(), regex, sub));
        }
        Ok(out)
    }

    fn compile_pattern_properties(&mut self, v: &Value, loc: &Location, base: &Rc<str>, draft: Draft) -> Result<NodeId, CompileError> {
        let pats = self.compile_pattern_map(v, loc, base, draft)?;
        Ok(self.push(Kind::PatternProperties(pats), loc.child("patternProperties"), "patternProperties", base, draft))
    }

    /// Compile a reference target; returns the node of the target schema and
    /// whether it was a lazy (cyclic) reference. Returns None when the target is
    /// the schema currently being compiled (self reference).
    fn compile_target(&mut self, resolved: &Resolved, self_id: NodeId) -> Result<Option<(NodeId, bool)>, CompileError> {
        let key = format!("{}#{}", resolved.base, resolved.pointer);
        let anchor_key = if resolved.pointer.is_empty() {
            // target may be a resource root or an anchor; use value identity via pointer
            None
        } else {
            None
        };
        let _ = anchor_key;
        if let Some(&existing) = self.cache.get(&key) {
            if existing == self_id {
                return Ok(None);
            }
            let lazy = self.in_progress.contains(&key);
            return Ok(Some((existing, lazy)));
        }
        let loc = Location {
            base: Rc::from(resolved.base.as_str()),
            pointer: resolved.pointer.clone(),
        };
        let base: Rc<str> = Rc::from(resolved.base.as_str());
        let id = self.compile_cached(&resolved.value, loc, base, resolved.draft, key)?;
        Ok(Some((id, false)))
    }

    fn compile_ref(&mut self, v: &Value, loc: &Location, base: &Rc<str>, draft: Draft, self_id: NodeId) -> Result<Option<NodeId>, CompileError> {
        let reference = match v {
            Value::String(s) => s,
            other => return Err(type_error(other, &["string"])),
        };
        let resolved = self.registry.resolve(base, reference, draft)?;
        let target = match self.compile_target(&resolved, self_id)? {
            Some(t) => t,
            None => return Ok(None),
        };
        let kloc = Location {
            base: loc.base.clone(),
            pointer: resolved.pointer.clone(),
        };
        Ok(Some(self.push(
            Kind::Ref {
                target: target.0,
                lazy: target.1,
            },
            kloc,
            "$ref",
            base,
            draft,
        )))
    }

    fn compile_dynamic_ref(&mut self, v: &Value, loc: &Location, base: &Rc<str>, draft: Draft, self_id: NodeId) -> Result<Option<NodeId>, CompileError> {
        let reference = match v {
            Value::String(s) => s,
            other => return Err(type_error(other, &["string"])),
        };
        let resolved = self.registry.resolve(base, reference, draft)?;
        let fallback = match self.compile_target(&resolved, self_id)? {
            Some(t) => t,
            None => return Ok(None),
        };
        // Determine whether the fragment is a plain-name dynamic anchor.
        let frag = reference.rsplit('#').next().filter(|_| reference.contains('#')).unwrap_or("");
        let mut anchor = None;
        let mut candidates = Vec::new();
        if !frag.is_empty() && !frag.starts_with('/') {
            // The initial target must itself have a matching $dynamicAnchor.
            let target_has_dyn = resolved
                .value
                .as_object()
                .and_then(|o| o.get("$dynamicAnchor"))
                .and_then(|a| a.as_str())
                .map_or(false, |a| a == frag);
            if target_has_dyn {
                anchor = Some(frag.to_string());
                candidates = self.dynamic_candidates(frag, self_id)?;
            }
        }
        let kloc = Location {
            base: loc.base.clone(),
            pointer: resolved.pointer.clone(),
        };
        Ok(Some(self.push(
            Kind::DynamicRef {
                anchor,
                fallback: fallback.0,
                lazy: fallback.1,
                candidates,
            },
            kloc,
            "$dynamicRef",
            base,
            draft,
        )))
    }

    /// Compile all resources that declare `$dynamicAnchor: name`.
    fn dynamic_candidates(&mut self, name: &str, self_id: NodeId) -> Result<Vec<(String, NodeId)>, CompileError> {
        if let Some(c) = self.dynamic_targets.get(name) {
            return Ok(c.clone());
        }
        // Collect all known resources with the anchor.
        let bases = self.registry.resources_with_dynamic_anchor(name);
        let mut out = Vec::new();
        for b in bases {
            if let Some(t) = self.registry.dynamic_anchor(&b, name) {
                let res = self.registry.get_resource(&b).unwrap();
                let resolved = Resolved {
                    value: t.value.clone(),
                    base: b.clone(),
                    draft: res.draft,
                    pointer: String::new(),
                    doc: res.doc.clone(),
                };
                // Use a distinct cache key for anchor targets with pointer
                let key = format!("{}#{}", b, t.pointer);
                let id = if let Some(&existing) = self.cache.get(&key) {
                    existing
                } else {
                    let loc = Location {
                        base: Rc::from(b.as_str()),
                        pointer: t.pointer.clone(),
                    };
                    let base: Rc<str> = Rc::from(b.as_str());
                    self.compile_cached(&resolved.value, loc, base, resolved.draft, key)?
                };
                let _ = self_id;
                out.push((b.clone(), id));
            }
        }
        self.dynamic_targets.insert(name.to_string(), out.clone());
        Ok(out)
    }

    fn compile_recursive_ref(&mut self, v: &Value, loc: &Location, base: &Rc<str>, draft: Draft, self_id: NodeId) -> Result<Option<NodeId>, CompileError> {
        let reference = match v {
            Value::String(s) => s,
            other => return Err(type_error(other, &["string"])),
        };
        let resolved = self.registry.resolve(base, reference, draft)?;
        let fallback = match self.compile_target(&resolved, self_id)? {
            Some(t) => t,
            None => return Ok(None),
        };
        let mut candidates = Vec::new();
        let target_has_anchor = resolved
            .value
            .as_object()
            .and_then(|o| o.get("$recursiveAnchor"))
            .map_or(false, |a| a == &Value::Bool(true));
        if target_has_anchor {
            if self.recursive_targets.is_empty() {
                let bases = self.registry.resources_with_recursive_anchor();
                let mut out = Vec::new();
                for b in bases {
                    let res = self.registry.get_resource(&b).unwrap();
                    let key = format!("{}#{}", b, res.pointer);
                    let id = if let Some(&existing) = self.cache.get(&key) {
                        existing
                    } else {
                        let loc = Location {
                            base: Rc::from(b.as_str()),
                            pointer: res.pointer.clone(),
                        };
                        let base: Rc<str> = Rc::from(b.as_str());
                        self.compile_cached(&res.value.clone(), loc, base, res.draft, key)?
                    };
                    out.push((b.clone(), id));
                }
                self.recursive_targets = out;
            }
            candidates = self.recursive_targets.clone();
        }
        let kloc = Location {
            base: loc.base.clone(),
            pointer: resolved.pointer.clone(),
        };
        Ok(Some(self.push(
            Kind::RecursiveRef {
                fallback: fallback.0,
                lazy: fallback.1,
                candidates,
            },
            kloc,
            "$recursiveRef",
            base,
            draft,
        )))
    }
}

fn parse_types(v: &Value) -> Result<Vec<JsonType>, CompileError> {
    match v {
        Value::String(s) => match JsonType::parse(s) {
            Some(t) => Ok(vec![t]),
            None => Err(CompileError("Unexpected type".to_string())),
        },
        Value::Array(arr) => {
            let mut set: Vec<JsonType> = Vec::new();
            for item in arr {
                match item {
                    Value::String(s) => match JsonType::parse(s) {
                        Some(t) => {
                            if !set.contains(&t) {
                                set.push(t)
                            }
                        }
                        None => return Err(CompileError("Unexpected type".to_string())),
                    },
                    other => return Err(type_error(other, &["string"])),
                }
            }
            set.sort();
            Ok(set)
        }
        other => Err(type_error(other, &["array", "string"])),
    }
}

fn parse_non_negative(v: &Value) -> Result<u64, CompileError> {
    match v {
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                return Ok(u);
            }
            if let Some(i) = n.as_i64() {
                return Ok(if i < 0 { 0 } else { i as u64 });
            }
            let num = Num::from_json(n);
            if num.f.is_finite() && num.f.fract() == 0.0 {
                if num.f < 0.0 {
                    Ok(0)
                } else {
                    Ok(num.f as u64)
                }
            } else {
                Err(type_error(v, &["integer"]))
            }
        }
        other => Err(type_error(other, &["integer"])),
    }
}

fn parse_string_array(v: &Value) -> Result<Vec<String>, CompileError> {
    match v {
        Value::Array(arr) => {
            let mut out = Vec::new();
            for item in arr {
                match item {
                    Value::String(s) => out.push(s.clone()),
                    other => return Err(type_error(other, &["string"])),
                }
            }
            Ok(out)
        }
        other => Err(type_error(other, &["array"])),
    }
}

/// Helper used by unevaluated* to see which sibling nodes exist.
pub fn schema_children(nodes: &[Node], id: NodeId) -> &[NodeId] {
    match &nodes[id].kind {
