{"command":"cat > /workspace/src/eval.rs <<'EOF'
//! Schema evaluation: validity checks, error listing (text output) and
//! annotated output units (list/hierarchical output).

use crate::num::{self, Num};
use crate::registry::escape_pointer;
use crate::schema::{Dep, JsonType, Kind, Node, NodeId, Sub};
use serde_json::{Map, Value};
use std::cmp::Ordering;
use std::collections::BTreeSet;
use std::rc::Rc;

#[derive(Debug, Clone)]
pub struct Unit {
    pub valid: bool,
    pub eval_path: String,
    pub inst_path: String,
    pub schema_loc: String,
    pub annotations: Option<Value>,
    pub errors: Vec<(String, String)>,
    pub children: Vec<Unit>,
}

impl Unit {
    fn new(valid: bool, eval_path: &str, inst_path: &str, schema_loc: String) -> Unit {
        Unit {
            valid,
            eval_path: eval_path.to_string(),
            inst_path: inst_path.to_string(),
            schema_loc,
            annotations: None,
            errors: Vec::new(),
            children: Vec::new(),
        }
    }

    fn with_error(mut self, keyword: &str, message: String) -> Unit {
        self.valid = false;
        self.errors.push((keyword.to_string(), message));
        self
    }

    /// Serialize to JSON (list entry / hierarchical node).
    pub fn to_json(&self, hierarchical: bool) -> Value {
        let mut m = Map::new();
        m.insert("evaluationPath".into(), Value::String(self.eval_path.clone()));
        m.insert("instanceLocation".into(), Value::String(self.inst_path.clone()));
        m.insert("schemaLocation".into(), Value::String(self.schema_loc.clone()));
        m.insert("valid".into(), Value::Bool(self.valid));
        if let Some(a) = &self.annotations {
            let key = if self.valid { "annotations" } else { "droppedAnnotations" };
            m.insert(key.into(), a.clone());
        }
        if !self.errors.is_empty() {
            let mut em: Map<String, Value> = Map::new();
            for (k, msg) in &self.errors {
                match em.get_mut(k) {
                    None => {
                        em.insert(k.clone(), Value::String(msg.clone()));
                    }
                    Some(Value::String(prev)) => {
                        let arr = vec![Value::String(prev.clone()), Value::String(msg.clone())];
                        em.insert(k.clone(), Value::Array(arr));
                    }
                    Some(Value::Array(arr)) => arr.push(Value::String(msg.clone())),
                    _ => {}
                }
            }
            m.insert("errors".into(), Value::Object(em));
        }
        if hierarchical && !self.children.is_empty() {
            let details: Vec<Value> = self.children.iter().map(|c| c.to_json(true)).collect();
            m.insert("details".into(), Value::Array(details));
        }
        Value::Object(m)
    }

    /// Flatten into a pre-order list.
    pub fn flatten(&self, out: &mut Vec<Value>) {
        out.push(self.to_json(false));
        for c in &self.children {
            c.flatten(out);
        }
    }

    fn collect_errors(&self, out: &mut Vec<(String, String)>) {
        for e in &self.errors {
            out.push(e.clone());
        }
        for c in &self.children {
            c.collect_errors(out);
        }
    }
}

pub fn fmt(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

/// Deep JSON equality with exact numeric comparison.
pub fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => num::num_eq(x, y),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| json_eq(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).map_or(false, |w| json_eq(v, w)))
        }
        _ => a == b,
    }
}

fn join_path(base: &str, seg: &str) -> String {
    format!("{}/{}", base, escape_pointer(seg))
}

fn join_idx(base: &str, idx: usize) -> String {
    format!("{}/{}", base, idx)
}

fn plural(n: u64, one: &str, many: &str) -> String {
    if n == 1 {
        format!("{} {}", n, one)
    } else {
        format!("{} {}", n, many)
    }
}

fn types_message(inst: &Value, types: &[JsonType], output_mode: bool) -> String {
    if types.len() == 1 {
        format!("{} is not of type \"{}\"", fmt(inst), types[0].name())
    } else if output_mode {
        let names: Vec<&str> = types.iter().map(|t| t.name()).collect();
        format!("{} is not of types ({})", fmt(inst), names.join(", "))
    } else {
        let names: Vec<String> = types.iter().map(|t| format!("\"{}\"", t.name())).collect();
        format!("{} is not of types {}", fmt(inst), names.join(", "))
    }
}

fn enum_message(inst: &Value, options: &[Value]) -> String {
    let items: Vec<String> = options.iter().map(fmt).collect();
    let list = match items.len() {
        0 => String::new(),
        1 => items[0].clone(),
        2 => format!("{} or {}", items[0], items[1]),
        3 => format!("{}, {} or {}", items[0], items[1], items[2]),
        n => format!("{}, {} or {} other candidates", items[0], items[1], n - 2),
    };
    format!("{} is not one of {}", fmt(inst), list)
}

fn unexpected_list(items: &[String]) -> String {
    let quoted: Vec<String> = items.iter().map(|s| format!("'{}'", s)).collect();
    if quoted.len() == 1 {
        format!("({} was unexpected)", quoted[0])
    } else {
        format!("({} were unexpected)", quoted.join(", "))
    }
}

fn has_duplicates(items: &[Value]) -> bool {
    for i in 0..items.len() {
        for j in (i + 1)..items.len() {
            if json_eq(&items[i], &items[j]) {
                return true;
            }
        }
    }
    false
}

fn content_check(encoding: &Option<String>, media_type: &Option<String>, s: &str) -> Result<(), (&'static str, String)> {
    let mut decoded: Option<Vec<u8>> = None;
    if encoding.as_deref() == Some("base64") {
        match crate::content::base64_decode(s) {
            Some(d) => decoded = Some(d),
            None => {
                return Err((
                    "contentEncoding",
                    format!("{} is not compliant with \"base64\" content encoding", fmt(&Value::String(s.to_string()))),
                ))
            }
        }
    }
    if media_type.as_deref() == Some("application/json") {
        let ok = match &decoded {
            Some(d) => serde_json::from_slice::<Value>(d).is_ok(),
            None => serde_json::from_str::<Value>(s).is_ok(),
        };
        if !ok {
            return Err((
                "contentMediaType",
                format!("{} is not compliant with \"application/json\" media type", fmt(&Value::String(s.to_string()))),
            ));
        }
    }
    Ok(())
}

pub struct Evaluator<'a> {
    pub nodes: &'a [Node],
    dyn_scope: Vec<Rc<str>>,
    lazy_stack: Vec<(NodeId, String)>,
}

impl<'a> Evaluator<'a> {
    pub fn new(nodes: &'a [Node]) -> Evaluator<'a> {
        Evaluator {
            nodes,
            dyn_scope: Vec::new(),
            lazy_stack: Vec::new(),
        }
    }

    fn node(&self, id: NodeId) -> &'a Node {
        &self.nodes[id]
    }

    fn enter_scope(&mut self, id: NodeId) -> bool {
        let base = &self.nodes[id].base;
        if self.dyn_scope.last().map_or(true, |b| b != base) {
            self.dyn_scope.push(base.clone());
            true
        } else {
            false
        }
    }

    fn leave_scope(&mut self, pushed: bool) {
        if pushed {
            self.dyn_scope.pop();
        }
    }

    fn resolve_dynamic(&self, fallback: NodeId, candidates: &[(String, NodeId)]) -> NodeId {
        for base in &self.dyn_scope {
            for (cb, id) in candidates {
                if cb.as_str() == &**base {
                    return *id;
                }
            }
        }
        fallback
    }

    fn sub_valid(&mut self, sub: &Sub, inst: &Value, inst_path: &str) -> bool {
        match sub {
            Sub::False => false,
            Sub::Node(id) => self.is_valid(*id, inst, inst_path),
        }
    }

    // ------------------------------------------------------------------
    // Validity
    // ------------------------------------------------------------------

    pub fn is_valid(&mut self, id: NodeId, inst: &Value, inst_path: &str) -> bool {
        let node = self.node(id);
        match &node.kind {
            Kind::Schema { children, .. } => {
                let pushed = self.enter_scope(id);
                let mut ok = true;
                for &c in children {
                    if !self.is_valid(c, inst, inst_path) {
                        ok = false;
                        break;
                    }
                }
                self.leave_scope(pushed);
                ok
            }
            Kind::False => false,
            Kind::Type(types) => types.iter().any(|t| t.matches(inst)),
            Kind::Const(c) => json_eq(inst, c),
            Kind::Enum(options) => options.iter().any(|o| json_eq(inst, o)),
            Kind::Minimum(n) => number_cmp(inst, n, |o| o != Ordering::Less),
            Kind::Maximum(n) => number_cmp(inst, n, |o| o != Ordering::Greater),
            Kind::ExclusiveMinimum(n) | Kind::Minimum4Exclusive(n) => number_cmp(inst, n, |o| o == Ordering::Greater),
            Kind::ExclusiveMaximum(n) | Kind::Maximum4Exclusive(n) => number_cmp(inst, n, |o| o == Ordering::Less),
            Kind::MultipleOf(n) => match inst {
                Value::Number(x) => num::is_multiple_of(&Num::from_json(x), n),
                _ => true,
            },
            Kind::MinLength(n) => match inst {
                Value::String(s) => s.chars().count() as u64 >= *n,
                _ => true,
            },
            Kind::MaxLength(n) => match inst {
                Value::String(s) => s.chars().count() as u64 <= *n,
                _ => true,
            },
            Kind::MinItems(n) => match inst {
                Value::Array(a) => a.len() as u64 >= *n,
                _ => true,
            },
            Kind::MaxItems(n) => match inst {
                Value::Array(a) => a.len() as u64 <= *n,
                _ => true,
            },
            Kind::MinProperties(n) => match inst {
                Value::Object(o) => o.len() as u64 >= *n,
                _ => true,
            },
            Kind::MaxProperties(n) => match inst {
                Value::Object(o) => o.len() as u64 <= *n,
                _ => true,
            },
            Kind::Required(names) => match inst {
                Value::Object(o) => names.iter().all(|n| o.contains_key(n)),
                _ => true,
            },
            Kind::Pattern { regex, .. } => match inst {
                Value::String(s) => regex.is_match(s).unwrap_or(false),
                _ => true,
            },
            Kind::Format(name) => match inst {
                Value::String(s) => crate::formats::check(name, s),
                _ => true,
            },
            Kind::UniqueItems => match inst {
                Value::Array(a) => !has_duplicates(a),
                _ => true,
            },
            Kind::Content { encoding, media_type } => match inst {
                Value::String(s) => content_check(encoding, media_type, s).is_ok(),
                _ => true,
            },
            Kind::Properties(props) => match inst {
                Value::Object(o) => {
                    for (name, sub) in props {
                        if let Some(v) = o.get(name) {
                            if !self.is_valid(*sub, v, &join_path(inst_path, name)) {
                                return false;
                            }
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::PatternProperties(pats) => match inst {
                Value::Object(o) => {
                    for (_, re, sub) in pats {
                        for (k, v) in o {
                            if re.is_match(k).unwrap_or(false) && !self.is_valid(*sub, v, &join_path(inst_path, k)) {
                                return false;
                            }
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::AdditionalProperties {
                properties,
                patterns,
                additional,
            } => match inst {
                Value::Object(o) => {
                    for (k, v) in o {
                        let path = join_path(inst_path, k);
                        let mut handled = false;
                        if let Some((_, sub)) = properties.iter().find(|(n, _)| n == k) {
                            handled = true;
                            if !self.is_valid(*sub, v, &path) {
                                return false;
                            }
                        }
                        for (_, re, sub) in patterns {
                            if re.is_match(k).unwrap_or(false) {
                                handled = true;
                                if !self.is_valid(*sub, v, &path) {
                                    return false;
                                }
                            }
                        }
                        if !handled && !self.sub_valid(additional, v, &path) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::PropertyNames(sub) => match inst {
                Value::Object(o) => {
                    for k in o.keys() {
                        if !self.is_valid(*sub, &Value::String(k.clone()), inst_path) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::Items(sub) => match inst {
                Value::Array(a) => {
                    for (i, v) in a.iter().enumerate() {
                        if !self.is_valid(*sub, v, &join_idx(inst_path, i)) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::ItemsType(types) => match inst {
                Value::Array(a) => a.iter().all(|v| types.iter().any(|t| t.matches(v))),
                _ => true,
            },
            Kind::ItemsArray(subs) => match inst {
                Value::Array(a) => {
                    for (i, (v, sub)) in a.iter().zip(subs.iter()).enumerate() {
                        if !self.is_valid(*sub, v, &join_idx(inst_path, i)) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::AdditionalItems { prefix_len, schema } => match inst {
                Value::Array(a) => {
                    for (i, v) in a.iter().enumerate().skip(*prefix_len) {
                        if !self.sub_valid(schema, v, &join_idx(inst_path, i)) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::PrefixItems(subs) => match inst {
                Value::Array(a) => {
                    for (i, (v, sub)) in a.iter().zip(subs.iter()).enumerate() {
                        if !self.is_valid(*sub, v, &join_idx(inst_path, i)) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::Contains { node, min, max } => match inst {
                Value::Array(a) => {
                    let mut count = 0u64;
                    for (i, v) in a.iter().enumerate() {
                        if self.is_valid(*node, v, &join_idx(inst_path, i)) {
                            count += 1;
                        }
                    }
                    let min = min.unwrap_or(1);
                    count >= min && max.map_or(true, |m| count <= m)
                }
                _ => true,
            },
            Kind::DependentRequired(deps) => match inst {
                Value::Object(o) => deps
                    .iter()
                    .all(|(p, req)| !o.contains_key(p) || req.iter().all(|r| o.contains_key(r))),
                _ => true,
            },
            Kind::DependentSchemas(deps) => match inst {
                Value::Object(o) => {
                    for (p, sub) in deps {
                        if o.contains_key(p) && !self.is_valid(*sub, inst, inst_path) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::Dependencies(deps) => match inst {
                Value::Object(o) => {
                    for (p, dep) in deps {
                        if !o.contains_key(p) {
                            continue;
                        }
                        match dep {
                            Dep::Required(req) => {
                                if !req.iter().all(|r| o.contains_key(r)) {
                                    return false;
                                }
                            }
                            Dep::Schema(sub) => {
                                if !self.is_valid(*sub, inst, inst_path) {
                                    return false;
                                }
                            }
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::AllOf(subs) => {
                for &s in subs {
                    if !self.is_valid(s, inst, inst_path) {
                        return false;
                    }
                }
                true
            }
            Kind::AnyOf(subs) => {
                for &s in subs {
                    if self.is_valid(s, inst, inst_path) {
                        return true;
                    }
                }
                false
            }
            Kind::OneOf(subs) => {
                let mut count = 0;
                for &s in subs {
                    if self.is_valid(s, inst, inst_path) {
                        count += 1;
                        if count > 1 {
                            return false;
                        }
                    }
                }
                count == 1
            }
            Kind::Not { node, .. } => !self.is_valid(*node, inst, inst_path),
            Kind::IfThenElse { cond, then, otherwise } => {
                if self.is_valid(*cond, inst, inst_path) {
                    then.map_or(true, |t| self.is_valid(t, inst, inst_path))
                } else {
                    otherwise.map_or(true, |e| self.is_valid(e, inst, inst_path))
                }
            }
            Kind::UnevaluatedProperties { schema, parent } => match inst {
                Value::Object(o) => {
                    let evaluated = self.evaluated_properties(*parent, id, inst, inst_path);
                    for (k, v) in o {
                        if !evaluated.contains(k) && !self.sub_valid(schema, v, &join_path(inst_path, k)) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::UnevaluatedItems { schema, parent } => match inst {
                Value::Array(a) => {
                    let evaluated = self.evaluated_items(*parent, id, inst, inst_path);
                    for (i, v) in a.iter().enumerate() {
                        if !evaluated.contains(&i) && !self.sub_valid(schema, v, &join_idx(inst_path, i)) {
                            return false;
                        }
                    }
                    true
                }
                _ => true,
            },
            Kind::Ref { target, lazy } => self.ref_valid(id, *target, *lazy, inst, inst_path),
            Kind::DynamicRef {
                fallback,
                lazy,
                candidates,
                ..
            } => {
                let target = self.resolve_dynamic(*fallback, candidates);
                self.ref_valid(id, target, *lazy, inst, inst_path)
            }
            Kind::RecursiveRef {
                fallback,
                lazy,
                candidates,
            } => {
                let target = self.resolve_dynamic(*fallback, candidates);
                self.ref_valid(id, target, *lazy, inst, inst_path)
            }
        }
    }

    fn ref_valid(&mut self, id: NodeId, target: NodeId, lazy: bool, inst: &Value, inst_path: &str) -> bool {
        if lazy {
            let key = (id, inst_path.to_string());
            if self.lazy_stack.contains(&key) {
                return true;
            }
            self.lazy_stack.push(key);
            let r = self.is_valid(target, inst, inst_path);
            self.lazy_stack.pop();
            r
        } else {
            self.is_valid(target, inst, inst_path)
        }
    }

    // ------------------------------------------------------------------
    // Evaluated properties / items (for unevaluated*)
    // ------------------------------------------------------------------

    fn evaluated_properties(&mut self, schema: NodeId, skip: NodeId, inst: &Value, inst_path: &str) -> BTreeSet<String> {
        let mut out = BTreeSet::new();
        let mut all = false;
        self.collect_props(schema, skip, inst, inst_path, &mut out, &mut all, 0);
        if all {
            if let Value::Object(o) = inst {
                for k in o.keys() {
                    out.insert(k.clone());
                }
            }
        }
        out
    }

    fn collect_props(
        &mut self,
        schema: NodeId,
        skip: NodeId,
        inst: &Value,
        inst_path: &str,
        out: &mut BTreeSet<String>,
        all: &mut bool,
        depth: usize,
    ) {
        if depth > 64 {
            return;
        }
        let obj = match inst {
            Value::Object(o) => o,
            _ => return,
        };
        let children: Vec<NodeId> = match &self.nodes[schema].kind {
            Kind::Schema { children, .. } => children.clone(),
            _ => return,
        };
        for c in children {
            if c == skip {
                continue;
            }
            match &self.nodes[c].kind {
                Kind::Properties(props) => {
                    for (name, _) in props {
                        if obj.contains_key(name) {
                            out.insert(name.clone());
                        }
                    }
                }
                Kind::PatternProperties(pats) => {
                    for (_, re, _) in pats {
                        for k in obj.keys() {
                            if re.is_match(k).unwrap_or(false) {
                                out.insert(k.clone());
                            }
                        }
                    }
                }
                Kind::AdditionalProperties { .. } => {
                    *all = true;
                }
                Kind::UnevaluatedProperties { .. } => {
                    *all = true;
                }
                Kind::Ref { target, lazy } => {
                    let target = *target;
                    let lazy = *lazy;
                    if lazy {
                        let key = (c, inst_path.to_string());
                        if self.lazy_stack.contains(&key) {
                            continue;
                        }
                        self.lazy_stack.push(key);
                        self.collect_props(target, usize::MAX, inst, inst_path, out, all, depth + 1);
                        self.lazy_stack.pop();
                    } else {
                        self.collect_props(target, usize::MAX, inst, inst_path, out, all, depth + 1);
                    }
                }
                Kind::DynamicRef {
                    fallback,
                    candidates,
                    ..
                }
                | Kind::RecursiveRef {
                    fallback,
                    candidates,
                    ..
                } => {
                    let target = self.resolve_dynamic(*fallback, candidates);
                    let key = (c, inst_path.to_string());
                    if self.lazy_stack.contains(&key) {
                        continue;
                    }
                    self.lazy_stack.push(key);
                    self.collect_props(target, usize::MAX, inst, inst_path, out, all, depth + 1);
                    self.lazy_stack.pop();
                }
                Kind::AllOf(subs) | Kind::AnyOf(subs) | Kind::OneOf(subs) => {
                    let subs = subs.clone();
                    for s in subs {
                        if self.is_valid(s, inst, inst_path) {
                            self.collect_props(s, usize::MAX, inst, inst_path, out, all, depth + 1);
                        }
                    }
                }
                Kind::IfThenElse { cond, then, otherwise } => {
                    let (cond, then, otherwise) = (*cond, *then, *otherwise);
                    if self.is_valid(cond, inst, inst_path) {
                        self.collect_props(cond, usize::MAX, inst, inst_path, out, all, depth + 1);
                        if let Some(t) = then {
                            if self.is_valid(t, inst, inst_path) {
                                self.collect_props(t, usize::MAX, inst, inst_path, out, all, depth + 1);
                            }
                        }
                    } else if let Some(e) = otherwise {
                        if self.is_valid(e, inst, inst_path) {
                            self.collect_props(e, usize::MAX, inst, inst_path, out, all, depth + 1);
                        }
                    }
                }
                Kind::DependentSchemas(deps) => {
                    let deps = deps.clone();
                    for (p, s) in deps {
                        if obj.contains_key(&p) && self.is_valid(s, inst, inst_path) {
                            self.collect_props(s, usize::MAX, inst, inst_path, out, all, depth + 1);
                        }
                    }
                }
                Kind::Dependencies(deps) => {
                    let deps = deps.clone();
                    for (p, d) in deps {
                        if let Dep::Schema(s) = d {
                            if obj.contains_key(&p) && self.is_valid(s, inst, inst_path) {
                                self.collect_props(s, usize::MAX, inst, inst_path, out, all, depth + 1);
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }

    fn evaluated_items(&mut self, schema: NodeId, skip: NodeId, inst: &Value, inst_path: &str) -> BTreeSet<usize> {
        let mut out = BTreeSet::new();
        let mut all = false;
        self.collect_items(schema, skip, inst, inst_path, &mut out, &mut all, 0);
        if all {
            if let Value::Array(a) = inst {
                for i in 0..a.len() {
                    out.insert(i);
                }
            }
        }
        out
    }

    fn collect_items(
        &mut self,
        schema: NodeId,
        skip: NodeId,
        inst: &Value,
        inst_path: &str,
        out: &mut BTreeSet<usize>,
        all: &mut bool,
        depth: usize,
    ) {
        if depth > 64 {
            return;
        }
        let arr = match inst {
            Value::Array(a) => a,
            _ => return,
        };
        let children: Vec<NodeId> = match &self.nodes[schema].kind {
            Kind::Schema { children, .. } => children.clone(),
            _ => return,
        };
        for c in children {
            if c == skip {
                continue;
            }
            match &self.nodes[c].kind {
                Kind::PrefixItems(subs) | Kind::ItemsArray(subs) => {
                    for i in 0..subs.len().min(arr.len()) {
                        out.insert(i);
                    }
                }
                Kind::Items(_) | Kind::ItemsType(_) | Kind::AdditionalItems { .. } | Kind::UnevaluatedItems { .. } => {
                    *all = true;
                }
                Kind::Contains { node, .. } => {
                    let node = *node;
                    if self.nodes[c].draft == crate::draft::Draft::Draft202012 {
                        for (i, v) in arr.iter().enumerate() {
                            if self.is_valid(node, v, &join_idx(inst_path, i)) {
                                out.insert(i);
                            }
                        }
                    }
                }
                Kind::Ref { target, lazy } => {
                    let target = *target;
                    let lazy = *lazy;
                    if lazy {
                        let key = (c, inst_path.to_string());
                        if self.lazy_stack.contains(&key) {
                            continue;
                        }
                        self.lazy_stack.push(key);
                        self.collect_items(target, usize::MAX, inst, inst_path, out, all, depth + 1);
                        self.lazy_stack.pop();
                    } else {
                        self.collect_items(target, usize::MAX, inst, inst_path, out, all, depth + 1);
                    }
                }
                Kind::DynamicRef {
                    fallback,
                    candidates,
                    ..
                }
                | Kind::RecursiveRef {
                    fallback,
                    candidates,
                    ..
                } => {
                    let target = self.resolve_dynamic(*fallback, candidates);
                    let key = (c, inst_path.to_string());
                    if self.lazy_stack.contains(&key) {
                        continue;
                    }
                    self.lazy_stack.push(key);
                    self.collect_items(target, usize::MAX, inst, inst_path, out, all, depth + 1);
                    self.lazy_stack.pop();
                }
                Kind::AllOf(subs) | Kind::AnyOf(subs) | Kind::OneOf(subs) => {
                    let subs = subs.clone();
                    for s in subs {
                        if self.is_valid(s, inst, inst_path) {
                            self.collect_items(s, usize::MAX, inst, inst_path, out, all, depth + 1);
                        }
                    }
                }
                Kind::IfThenElse { cond, then, otherwise } => {
                    let (cond, then, otherwise) = (*cond, *then, *otherwise);
                    if self.is_valid(cond, inst, inst_path) {
                        self.collect_items(cond, usize::MAX, inst, inst_path, out, all, depth + 1);
                        if let Some(t) = then {
                            if self.is_valid(t, inst, inst_path) {
                                self.collect_items(t, usize::MAX, inst, inst_path, out, all, depth + 1);
                            }
                        }
                    } else if let Some(e) = otherwise {
                        if self.is_valid(e, inst, inst_path) {
                            self.collect_items(e, usize::MAX, inst, inst_path, out, all, depth + 1);
                        }
                    }
                }
                Kind::DependentSchemas(deps) => {
                    let deps = deps.clone();
                    for (_, s) in deps {
                        // dependentSchemas only applies to objects; arrays never trigger
                        let _ = s;
                    }
                }
                _ => {}
            }
        }
    }

    // ------------------------------------------------------------------
    // Text errors
    // ------------------------------------------------------------------

    pub fn errors(&mut self, id: NodeId, inst: &Value, inst_path: &str, out: &mut Vec<String>) {
        let node = self.node(id);
        match &node.kind {
            Kind::Schema { children, .. } => {
                let pushed = self.enter_scope(id);
                for &c in children {
                    self.errors(c, inst, inst_path, out);
                }
                self.leave_scope(pushed);
            }
            Kind::False => out.push(format!("False schema does not allow {}", fmt(inst))),
            Kind::Type(types) => {
                if !types.iter().any(|t| t.matches(inst)) {
                    out.push(types_message(inst, types, false));
                }
            }
            Kind::Const(c) => {
                if !json_eq(inst, c) {
                    out.push(format!("{} was expected", fmt(c)));
                }
            }
            Kind::Enum(options) => {
                if !options.iter().any(|o| json_eq(inst, o)) {
                    out.push(enum_message(inst, options));
                }
            }
            Kind::Minimum(n) => {
                if !number_cmp(inst, n, |o| o != Ordering::Less) {
                    out.push(format!("{} is less than the minimum of {}", fmt(inst), n.text));
                }
            }
            Kind::Maximum(n) => {
                if !number_cmp(inst, n, |o| o != Ordering::Greater) {
                    out.push(format!("{} is greater than the maximum of {}", fmt(inst), n.text));
                }
            }
            Kind::ExclusiveMinimum(n) | Kind::Minimum4Exclusive(n) => {
                if !number_cmp(inst, n, |o| o == Ordering::Greater) {
                    out.push(format!("{} is less than or equal to the minimum of {}", fmt(inst), n.text));
                }
            }
            Kind::ExclusiveMaximum(n) | Kind::Maximum4Exclusive(n) => {
                if !number_cmp(inst, n, |o| o == Ordering::Less) {
                    out.push(format!("{} is greater than or equal to the maximum of {}", fmt(inst), n.text));
                }
            }
            Kind::MultipleOf(n) => {
                if let Value::Number(x) = inst {
                    if !num::is_multiple_of(&Num::from_json(x), n) {
                        out.push(format!("{} is not a multiple of {}", fmt(inst), n.text));
                    }
                }
            }
            Kind::MinLength(n) => {
                if let Value::String(s) = inst {
                    if (s.chars().count() as u64) < *n {
                        out.push(format!("{} is shorter than {}", fmt(inst), plural(*n, "character", "characters")));
                    }
                }
            }
            Kind::MaxLength(n) => {
                if let Value::String(s) = inst {
                    if (s.chars().count() as u64) > *n {
                        out.push(format!("{} is longer than {}", fmt(inst), plural(*n, "character", "characters")));
                    }
                }
            }
            Kind::MinItems(n) => {
                if let Value::Array(a) = inst {
                    if (a.len() as u64) < *n {
                        out.push(format!("{} has less than {}", fmt(inst), plural(*n, "item", "items")));
                    }
                }
            }
            Kind::MaxItems(n) => {
                if let Value::Array(a) = inst {
                    if (a.len() as u64) > *n {
                        out.push(format!("{} has more than {}", fmt(inst), plural(*n, "item", "items")));
                    }
                }
            }
            Kind::MinProperties(n) => {
                if let Value::Object(o) = inst {
                    if (o.len() as u64) < *n {
                        out.push(format!("{} has less than {}", fmt(inst), plural(*n, "property", "properties")));
                    }
                }
            }
            Kind::MaxProperties(n) => {
                if let Value::Object(o) = inst {
                    if (o.len() as u64) > *n {
                        out.push(format!("{} has more than {}", fmt(inst), plural(*n, "property", "properties")));
                    }
                }
            }
            Kind::Required(names) => {
                if let Value::Object(o) = inst {
                    for n in names {
                        if !o.contains_key(n) {
                            out.push(format!("\"{}\" is a required property", n));
                        }
                    }
                }
            }
            Kind::Pattern { regex, display } => {
                if let Value::String(s) = inst {
                    if !regex.is_match(s).unwrap_or(false) {
                        out.push(format!("{} does not match \"{}\"", fmt(inst), display));
                    }
                }
            }
            Kind::Format(name) => {
                if let Value::String(s) = inst {
                    if !crate::formats::check(name, s) {
                        out.push(format!("{} is not a \"{}\"", fmt(inst), name));
                    }
                }
            }
            Kind::UniqueItems => {
                if let Value::Array(a) = inst {
                    if has_duplicates(a) {
                        out.push(format!("{} has non-unique elements", fmt(inst)));
                    }
                }
            }
            Kind::Content { encoding, media_type } => {
                if let Value::String(s) = inst {
                    if let Err((_, msg)) = content_check(encoding, media_type, s) {
                        out.push(msg);
                    }
                }
            }
            Kind::Properties(props) => {
                if let Value::Object(o) = inst {
                    for (name, sub) in props {
                        if let Some(v) = o.get(name) {
                            self.errors(*sub, v, &join_path(inst_path, name), out);
                        }
                    }
                }
            }
            Kind::PatternProperties(pats) => {
                if let Value::Object(o) = inst {
                    for (_, re, sub) in pats {
                        for (k, v) in o {
                            if re.is_match(k).unwrap_or(false) {
                                self.errors(*sub, v, &join_path(inst_path, k), out);
                            }
                        }
                    }
                }
            }
            Kind::AdditionalProperties {
                properties,
                patterns,
                additional,
            } => {
                if let Value::Object(o) = inst {
                    let mut unexpected = Vec::new();
                    for (k, v) in o {
                        let path = join_path(inst_path, k);
                        let mut handled = false;
                        if let Some((_, sub)) = properties.iter().find(|(n, _)| n == k) {
                            handled = true;
                            self.errors(*sub, v, &path, out);
                        }
                        for (_, re, sub) in patterns {
                            if re.is_match(k).unwrap_or(false) {
                                handled = true;
                                self.errors(*sub, v, &path, out);
                            }
                        }
                        if !handled {
                            match additional {
                                Sub::False => unexpected.push(k.clone()),
                                Sub::Node(sub) => self.errors(*sub, v, &path, out),
                            }
                        }
                    }
                    if !unexpected.is_empty() {
                        out.push(format!("Additional properties are not allowed {}", unexpected_list(&unexpected)));
                    }
                }
            }
            Kind::PropertyNames(sub) => {
                if let Value::Object(o) = inst {
                    for k in o.keys() {
                        self.errors(*sub, &Value::String(k.clone()), inst_path, out);
                    }
                }
            }
            Kind::Items(sub) => {
                if let Value::Array(a) = inst {
                    for (i, v) in a.iter().enumerate() {
                        self.errors(*sub, v, &join_idx(inst_path, i), out);
                    }
                }
            }
            Kind::ItemsType(types) => {
                if let Value::Array(a) = inst {
                    for v in a {
                        if !types.iter().any(|t| t.matches(v)) {
                            out.push(types_message(v, types, false));
                        }
                    }
                }
            }
            Kind::ItemsArray(subs) => {
                if let Value::Array(a) = inst {
                    for (i, (v, sub)) in a.iter().zip(subs.iter()).enumerate() {
                        self.errors(*sub, v, &join_idx(inst_path, i), out);
                    }
                }
            }
            Kind::AdditionalItems { prefix_len, schema } => {
                if let Value::Array(a) = inst {
                    match schema {
                        Sub::False => {
                            if a.len() > *prefix_len {
                                let extra: Vec<String> = a[*prefix_len..].iter().map(fmt).collect();
                                let joined = extra.join(", ");
                                if extra.len() == 1 {
                                    out.push(format!("Additional items are not allowed ({} was unexpected)", joined));
                                } else {
                                    out.push(format!("Additional items are not allowed ({} were unexpected)", joined));
                                }
                            }
                        }
                        Sub::Node(sub) => {
                            for (i, v) in a.iter().enumerate().skip(*prefix_len) {
                                self.errors(*sub, v, &join_idx(inst_path, i), out);
                            }
                        }
                    }
                }
            }
            Kind::PrefixItems(subs) => {
                if let Value::Array(a) = inst {
                    for (i, (v, sub)) in a.iter().zip(subs.iter()).enumerate() {
                        self.errors(*sub, v, &join_idx(inst_path, i), out);
                    }
                }
            }
            Kind::Contains { .. } => {
                if let Value::Array(_) = inst {
                    if !self.is_valid(id, inst, inst_path) {
                        out.push(format!("None of {} are valid under the given schema", fmt(inst)));
                    }
                }
            }
            Kind::DependentRequired(deps) => {
                if let Value::Object(o) = inst {
                    for (p, req) in deps {
                        if o.contains_key(p) {
                            for r in req {
                                if !o.contains_key(r) {
                                    out.push(format!("\"{}\" is a required property", r));
                                }
                            }
                        }
                    }
                }
            }
            Kind::DependentSchemas(deps) => {
                if let Value::Object(o) = inst {
                    for (p, sub) in deps {
                        if o.contains_key(p) {
                            self.errors(*sub, inst, inst_path, out);
                        }
                    }
                }
            }
            Kind::Dependencies(deps) => {
                if let Value::Object(o) = inst {
                    for (p, dep) in deps {
                        if !o.contains_key(p) {
                            continue;
                        }
                        match dep {
                            Dep::Required(req) => {
                                for r in req {
                                    if !o.contains_key(r) {
                                        out.push(format!("\"{}\" is a required property", r));
                                    }
                                }
                            }
                            Dep::Schema(sub) => self.errors(*sub, inst, inst_path, out),
                        }
                    }
                }
            }
            Kind::AllOf(subs) => {
                for &s in subs {
                    self.errors(s, inst, inst_path, out);
                }
            }
            Kind::AnyOf(subs) => {
                let subs = subs.clone();
                if !subs.iter().any(|&s| self.is_valid(s, inst, inst_path)) {
                    out.push(format!(
                        "{} is not valid under any of the schemas listed in the 'anyOf' keyword",
                        fmt(inst)
                    ));
                }
            }
            Kind::OneOf(subs) => {
                let subs = subs.clone();
                let count = subs.iter().filter(|&&s| self.is_valid(s, inst, inst_path)).count();
                if count == 0 {
                    out.push(format!(
                        "{} is not valid under any of the schemas listed in the 'oneOf' keyword",
                        fmt(inst)
                    ));
                } else if count > 1 {
                    out.push(format!(
                        "{} is valid under more than one of the schemas listed in the 'oneOf' keyword",
                        fmt(inst)
                    ));
                }
            }
            Kind::Not { node, schema } => {
                if self.is_valid(*node, inst, inst_path) {
                    out.push(format!("{} is not allowed for {}", fmt(schema), fmt(inst)));
                }
            }
            Kind::IfThenElse { cond, then, otherwise } => {
                let (cond, then, otherwise) = (*cond, *then, *otherwise);
                if self.is_valid(cond, inst, inst_path) {
                    if let Some(t) = then {
                        self.errors(t, inst, inst_path, out);
                    }
                } else if let Some(e) = otherwise {
                    self.errors(e, inst, inst_path, out);
                }
            }
            Kind::UnevaluatedProperties { schema, parent } => {
                if let Value::Object(o) = inst {
                    let evaluated = self.evaluated_properties(*parent, id, inst, inst_path);
                    let mut unexpected = Vec::new();
                    for (k, v) in o {
                        if !evaluated.contains(k) && !self.sub_valid(schema, v, &join_path(inst_path, k)) {
                            unexpected.push(k.clone());
                        }
                    }
                    if !unexpected.is_empty() {
                        out.push(format!("Unevaluated properties are not allowed {}", unexpected_list(&unexpected)));
                    }
                }
            }
            Kind::UnevaluatedItems { schema, parent } => {
                if let Value::Array(a) = inst {
                    let evaluated = self.evaluated_items(*parent, id, inst, inst_path);
                    let mut unexpected = Vec::new();
                    for (i, v) in a.iter().enumerate() {
                        if !evaluated.contains(&i) && !self.sub_valid(schema, v, &join_idx(inst_path, i)) {
                            unexpected.push(fmt(v));
                        }
                    }
                    if !unexpected.is_empty() {
                        out.push(format!("Unevaluated items are not allowed {}", unexpected_list(&unexpected)));
                    }
                }
            }
            Kind::Ref { target, lazy } => self.ref_errors(id, *target, *lazy, inst, inst_path, out),
            Kind::DynamicRef {
                fallback,
                lazy,
                candidates,
                ..
            }
            | Kind::RecursiveRef {
                fallback,
                lazy,
                candidates,
            } => {
                let target = self.resolve_dynamic(*fallback, candidates);
                self.ref_errors(id, target, *lazy, inst, inst_path, out);
            }
        }
    }

    fn ref_errors(&mut self, id: NodeId, target: NodeId, lazy: bool, inst: &Value, inst_path: &str, out: &mut Vec<String>) {
        if lazy {
            let key = (id, inst_path.to_string());
            if self.lazy_stack.contains(&key) {
                return;
            }
            self.lazy_stack.push(key);
            self.errors(target, inst, inst_path, out);
            self.lazy_stack.pop();
        } else {
            self.errors(target, inst, inst_path, out);
        }
    }

    // ------------------------------------------------------------------
    // Output units
    // ------------------------------------------------------------------

    pub fn evaluate(&mut self, id: NodeId, inst: &Value, eval_path: &str, inst_path: &str) -> Unit {
        let node = self.node(id);
        let loc = node.location.display();
        match &node.kind {
            Kind::Schema { children, annotations } => {
                let pushed = self.enter_scope(id);
                let mut unit = Unit::new(true, eval_path, inst_path, loc);
                for &c in children {
                    let kw = &self.nodes[c].keyword;
                    let child_path = join_path(eval_path, kw);
                    let cu = self.evaluate(c, inst, &child_path, inst_path);
                    if !cu.valid {
                        unit.valid = false;
                    }
                    unit.children.push(cu);
                }
                if !annotations.is_empty() {
                    unit.annotations = Some(Value::Object(annotations.clone()));
                }
                self.leave_scope(pushed);
                unit
            }
            Kind::False => Unit::new(true, eval_path, inst_path, loc)
                .with_error("falseSchema", format!("False schema does not allow {}", fmt(inst))),
            Kind::Type(types) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if !types.iter().any(|t| t.matches(inst)) {
                    u = u.with_error("type", types_message(inst, types, true));
                }
                u
            }
            Kind::Const(c) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if !json_eq(inst, c) {
                    u = u.with_error("const", format!("{} was expected", fmt(c)));
                }
                u
            }
            Kind::Enum(options) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if !options.iter().any(|o| json_eq(inst, o)) {
                    u = u.with_error("enum", enum_message(inst, options));
                }
                u
            }
            Kind::Minimum(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if !number_cmp(inst, n, |o| o != Ordering::Less) {
                    u = u.with_error("minimum", format!("{} is less than the minimum of {}", fmt(inst), n.text));
                }
                u
            }
            Kind::Maximum(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if !number_cmp(inst, n, |o| o != Ordering::Greater) {
                    u = u.with_error("maximum", format!("{} is greater than the maximum of {}", fmt(inst), n.text));
                }
                u
            }
            Kind::ExclusiveMinimum(n) | Kind::Minimum4Exclusive(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if !number_cmp(inst, n, |o| o == Ordering::Greater) {
                    u = u.with_error(
                        "exclusiveMinimum",
                        format!("{} is less than or equal to the minimum of {}", fmt(inst), n.text),
                    );
                }
                u
            }
            Kind::ExclusiveMaximum(n) | Kind::Maximum4Exclusive(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if !number_cmp(inst, n, |o| o == Ordering::Less) {
                    u = u.with_error(
                        "exclusiveMaximum",
                        format!("{} is greater than or equal to the maximum of {}", fmt(inst), n.text),
                    );
                }
                u
            }
            Kind::MultipleOf(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Number(x) = inst {
                    if !num::is_multiple_of(&Num::from_json(x), n) {
                        u = u.with_error("multipleOf", format!("{} is not a multiple of {}", fmt(inst), n.text));
                    }
                }
                u
            }
            Kind::MinLength(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::String(s) = inst {
                    if (s.chars().count() as u64) < *n {
                        u = u.with_error("minLength", format!("{} is shorter than {}", fmt(inst), plural(*n, "character", "characters")));
                    }
                }
                u
            }
            Kind::MaxLength(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::String(s) = inst {
                    if (s.chars().count() as u64) > *n {
                        u = u.with_error("maxLength", format!("{} is longer than {}", fmt(inst), plural(*n, "character", "characters")));
                    }
                }
                u
            }
            Kind::MinItems(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    if (a.len() as u64) < *n {
                        u = u.with_error("minItems", format!("{} has less than {}", fmt(inst), plural(*n, "item", "items")));
                    }
                }
                u
            }
            Kind::MaxItems(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    if (a.len() as u64) > *n {
                        u = u.with_error("maxItems", format!("{} has more than {}", fmt(inst), plural(*n, "item", "items")));
                    }
                }
                u
            }
            Kind::MinProperties(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    if (o.len() as u64) < *n {
                        u = u.with_error("minProperties", format!("{} has less than {}", fmt(inst), plural(*n, "property", "properties")));
                    }
                }
                u
            }
            Kind::MaxProperties(n) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    if (o.len() as u64) > *n {
                        u = u.with_error("maxProperties", format!("{} has more than {}", fmt(inst), plural(*n, "property", "properties")));
                    }
                }
                u
            }
            Kind::Required(names) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    for n in names {
                        if !o.contains_key(n) {
                            u = u.with_error("required", format!("\"{}\" is a required property", n));
                        }
                    }
                }
                u
            }
            Kind::Pattern { regex, display } => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::String(s) = inst {
                    if !regex.is_match(s).unwrap_or(false) {
                        u = u.with_error("pattern", format!("{} does not match \"{}\"", fmt(inst), display));
                    }
                }
                u
            }
            Kind::Format(name) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::String(s) = inst {
                    if !crate::formats::check(name, s) {
                        u = u.with_error("format", format!("{} is not a \"{}\"", fmt(inst), name));
                    }
                }
                u
            }
            Kind::UniqueItems => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    if has_duplicates(a) {
                        u = u.with_error("uniqueItems", format!("{} has non-unique elements", fmt(inst)));
                    }
                }
                u
            }
            Kind::Content { encoding, media_type } => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::String(s) = inst {
                    if let Err((kw, msg)) = content_check(encoding, media_type, s) {
                        u = u.with_error(kw, msg);
                    }
                }
                u
            }
            Kind::Properties(props) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    let mut matched = Vec::new();
                    for (name, sub) in props {
                        if let Some(v) = o.get(name) {
                            matched.push(Value::String(name.clone()));
                            let cu = self.evaluate(*sub, v, &join_path(eval_path, name), &join_path(inst_path, name));
                            if !cu.valid {
                                u.valid = false;
                            }
                            u.children.push(cu);
                        }
                    }
                    u.annotations = Some(Value::Array(matched));
                }
                u
            }
            Kind::PatternProperties(pats) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    let mut matched = Vec::new();
                    for (pat, re, sub) in pats {
                        for (k, v) in o {
                            if re.is_match(k).unwrap_or(false) {
                                matched.push(Value::String(k.clone()));
                                let cu = self.evaluate(*sub, v, &join_path(eval_path, pat), &join_path(inst_path, k));
                                if !cu.valid {
                                    u.valid = false;
                                }
                                u.children.push(cu);
                            }
                        }
                    }
                    u.annotations = Some(Value::Array(matched));
                }
                u
            }
            Kind::AdditionalProperties {
                properties,
                patterns,
                additional,
            } => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    let parent_path = parent_of(eval_path);
                    let mut additional_names: Vec<String> = Vec::new();
                    let mut pattern_matched: Vec<Value> = Vec::new();
                    for (k, v) in o {
                        let ipath = join_path(inst_path, k);
                        let mut handled = false;
                        if let Some((_, sub)) = properties.iter().find(|(n, _)| n == k) {
                            handled = true;
                            let p = join_path(&join_path(&parent_path, "properties"), k);
                            let cu = self.evaluate(*sub, v, &p, &ipath);
                            if !cu.valid {
                                u.valid = false;
                            }
                            u.children.push(cu);
                        }
                        for (pat, re, sub) in patterns {
                            if re.is_match(k).unwrap_or(false) {
                                handled = true;
                                pattern_matched.push(Value::String(k.clone()));
                                let p = join_path(&join_path(&parent_path, "patternProperties"), pat);
                                let cu = self.evaluate(*sub, v, &p, &ipath);
                                if !cu.valid {
                                    u.valid = false;
                                }
                                u.children.push(cu);
                            }
                        }
                        if !handled {
                            additional_names.push(k.clone());
                            match additional {
                                Sub::False => {}
                                Sub::Node(sub) => {
                                    let cu = self.evaluate(*sub, v, eval_path, &ipath);
                                    if !cu.valid {
                                        u.valid = false;
                                    }
                                    u.children.push(cu);
                                }
                            }
                        }
                    }
                    if properties.is_empty() && !patterns.is_empty() {
                        let pp_path = join_path(&parent_path, "patternProperties");
                        let pp_loc = {
                            let l = &self.nodes[id].location;
                            format!("{}#{}", l.base, format!("{}/patternProperties", parent_of(&l.pointer)))
                        };
                        let mut summary = Unit::new(true, &pp_path, inst_path, pp_loc);
                        summary.annotations = Some(Value::Array(pattern_matched));
                        u.children.push(summary);
                    }
                    match additional {
                        Sub::False => {
                            if !additional_names.is_empty() {
                                u = u.with_error(
                                    "additionalProperties",
                                    format!("Additional properties are not allowed {}", unexpected_list(&additional_names)),
                                );
                            }
                        }
                        Sub::Node(_) => {
                            u.annotations = Some(Value::Array(
                                additional_names.into_iter().map(Value::String).collect(),
                            ));
                        }
                    }
                }
                u
            }
            Kind::PropertyNames(sub) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    for k in o.keys() {
                        let cu = self.evaluate(*sub, &Value::String(k.clone()), eval_path, inst_path);
                        if !cu.valid {
                            u.valid = false;
                        }
                        u.children.push(cu);
                    }
                }
                u
            }
            Kind::Items(sub) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    for (i, v) in a.iter().enumerate() {
                        let cu = self.evaluate(*sub, v, eval_path, &join_idx(inst_path, i));
                        if !cu.valid {
                            u.valid = false;
                        }
                        u.children.push(cu);
                    }
                    u.annotations = Some(Value::Bool(!a.is_empty()));
                }
                u
            }
            Kind::ItemsType(types) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    for (i, v) in a.iter().enumerate() {
                        if !types.iter().any(|t| t.matches(v)) {
                            let msg = if types.len() == 1 {
                                format!("{} at index {} is not of type \"{}\"", fmt(v), i, types[0].name())
                            } else {
                                let names: Vec<&str> = types.iter().map(|t| t.name()).collect();
                                format!("{} at index {} is not of types ({})", fmt(v), i, names.join(", "))
                            };
                            u = u.with_error("type", msg);
                        }
                    }
                    u.annotations = Some(Value::Bool(!a.is_empty()));
                }
                u
            }
            Kind::ItemsArray(subs) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    for (i, (v, sub)) in a.iter().zip(subs.iter()).enumerate() {
                        let cu = self.evaluate(*sub, v, &join_idx(eval_path, i), &join_idx(inst_path, i));
                        if !cu.valid {
                            u.valid = false;
                        }
                        u.children.push(cu);
                    }
                }
                u
            }
            Kind::AdditionalItems { prefix_len, schema } => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    if a.len() > *prefix_len {
                        match schema {
                            Sub::False => {
                                let extra: Vec<String> = a[*prefix_len..].iter().map(fmt).collect();
                                let joined = extra.join(", ");
                                let msg = if extra.len() == 1 {
                                    format!("Additional items are not allowed ({} was unexpected)", joined)
                                } else {
                                    format!("Additional items are not allowed ({} were unexpected)", joined)
                                };
                                u = u.with_error("additionalItems", msg);
                            }
                            Sub::Node(sub) => {
                                for (i, v) in a.iter().enumerate().skip(*prefix_len) {
                                    let cu = self.evaluate(*sub, v, eval_path, &join_idx(inst_path, i));
                                    if !cu.valid {
                                        u.valid = false;
                                        let mut errs = Vec::new();
                                        cu.collect_errors(&mut errs);
                                        u.errors.extend(errs);
                                    }
                                }
                            }
                        }
                    }
                }
                u
            }
            Kind::PrefixItems(subs) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    for (i, (v, sub)) in a.iter().zip(subs.iter()).enumerate() {
                        let cu = self.evaluate(*sub, v, &join_idx(eval_path, i), &join_idx(inst_path, i));
                        if !cu.valid {
                            u.valid = false;
                        }
                        u.children.push(cu);
                    }
                    if !a.is_empty() {
                        if a.len() <= subs.len() {
                            u.annotations = Some(Value::Bool(true));
                        } else {
                            u.annotations = Some(Value::from(subs.len() - 1));
                        }
                    }
                }
                u
            }
            Kind::Contains { node, min, max } => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                let (node, min, max) = (*node, *min, *max);
                match inst {
                    Value::Array(a) => {
                        if min.is_none() && max.is_none() {
                            let mut matched = Vec::new();
                            let mut children = Vec::new();
                            for (i, v) in a.iter().enumerate() {
                                let cu = self.evaluate(node, v, eval_path, &join_idx(inst_path, i));
                                if cu.valid {
                                    matched.push(Value::from(i));
                                    children.push(cu);
                                }
                            }
                            if matched.is_empty() {
                                u = u.with_error("contains", format!("None of {} are valid under the given schema", fmt(inst)));
                            } else {
                                u.annotations = Some(Value::Array(matched));
                                u.children = children;
                            }
                        } else {
                            let mut count = 0u64;
                            for (i, v) in a.iter().enumerate() {
                                if self.is_valid(node, v, &join_idx(inst_path, i)) {
                                    count += 1;
                                }
                            }
                            let min_v = min.unwrap_or(1);
                            if !(count >= min_v && max.map_or(true, |m| count <= m)) {
                                u = u.with_error("contains", format!("None of {} are valid under the given schema", fmt(inst)));
                            }
                        }
                    }
                    _ => {
                        if min.is_none() && max.is_none() {
                            u.annotations = Some(Value::Array(Vec::new()));
                        }
                    }
                }
                u
            }
            Kind::DependentRequired(deps) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc.clone());
                if let Value::Object(o) = inst {
                    for (p, req) in deps {
                        if o.contains_key(p) {
                            let mut inner = Unit::new(true, eval_path, inst_path, loc.clone());
                            let mut req_unit = Unit::new(
                                true,
                                &join_idx(eval_path, 0),
                                inst_path,
                                format!("{}/0", loc),
                            );
                            for r in req {
                                if !o.contains_key(r) {
                                    req_unit = req_unit.with_error("required", format!("\"{}\" is a required property", r));
                                }
                            }
                            if !req_unit.valid {
                                inner.valid = false;
                                u.valid = false;
                            }
                            inner.children.push(req_unit);
                            u.children.push(inner);
                        }
                    }
                }
                u
            }
            Kind::DependentSchemas(deps) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    for (p, sub) in deps {
                        if o.contains_key(p) {
                            let cu = self.evaluate(*sub, inst, &join_path(eval_path, p), inst_path);
                            if !cu.valid {
                                u.valid = false;
                            }
                            u.children.push(cu);
                        }
                    }
                }
                u
            }
            Kind::Dependencies(deps) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc.clone());
                if let Value::Object(o) = inst {
                    for (p, dep) in deps {
                        if !o.contains_key(p) {
                            continue;
                        }
                        match dep {
                            Dep::Required(req) => {
                                let mut inner = Unit::new(true, eval_path, inst_path, loc.clone());
                                let mut req_unit = Unit::new(
                                    true,
                                    &join_idx(eval_path, 0),
                                    inst_path,
                                    format!("{}/0", loc),
                                );
                                for r in req {
                                    if !o.contains_key(r) {
                                        req_unit = req_unit.with_error("required", format!("\"{}\" is a required property", r));
                                    }
                                }
                                if !req_unit.valid {
                                    inner.valid = false;
                                    u.valid = false;
                                }
                                inner.children.push(req_unit);
                                u.children.push(inner);
                            }
                            Dep::Schema(sub) => {
                                let cu = self.evaluate(*sub, inst, &join_path(eval_path, p), inst_path);
                                if !cu.valid {
                                    u.valid = false;
                                }
                                u.children.push(cu);
                            }
                        }
                    }
                }
                u
            }
            Kind::AllOf(subs) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                for (i, &s) in subs.iter().enumerate() {
                    let cu = self.evaluate(s, inst, &join_idx(eval_path, i), inst_path);
                    if !cu.valid {
                        u.valid = false;
                    }
                    u.children.push(cu);
                }
                u
            }
            Kind::AnyOf(subs) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                let mut all = Vec::new();
                let mut found = None;
                for (i, &s) in subs.iter().enumerate() {
                    let cu = self.evaluate(s, inst, &join_idx(eval_path, i), inst_path);
                    if cu.valid {
                        found = Some(cu);
                        break;
                    }
                    all.push(cu);
                }
                match found {
                    Some(cu) => u.children.push(cu),
                    None => {
                        u.valid = false;
                        u.children = all;
                    }
                }
                u
            }
            Kind::OneOf(subs) => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                let mut all = Vec::new();
                for (i, &s) in subs.iter().enumerate() {
                    all.push(self.evaluate(s, inst, &join_idx(eval_path, i), inst_path));
                }
                let valid_count = all.iter().filter(|c| c.valid).count();
                if valid_count == 0 {
                    u.valid = false;
                    u.children = all;
                } else {
                    u.children = all.into_iter().filter(|c| c.valid).collect();
                    if valid_count > 1 {
                        u = u.with_error("oneOf", "more than one subschema succeeded".to_string());
                    }
                }
                u
            }
            Kind::Not { node, schema } => {
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if self.is_valid(*node, inst, inst_path) {
                    u = u.with_error("not", format!("{} is not allowed for {}", fmt(schema), fmt(inst)));
                }
                u
            }
            Kind::IfThenElse { cond, then, otherwise } => {
                let (cond, then, otherwise) = (*cond, *then, *otherwise);
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                let parent_path = parent_of(eval_path);
                let cu = self.evaluate(cond, inst, eval_path, inst_path);
                if cu.valid {
                    u.children.push(cu);
                    if let Some(t) = then {
                        let tu = self.evaluate(t, inst, &join_path(&parent_path, "then"), inst_path);
                        if !tu.valid {
                            u.valid = false;
                        }
                        u.children.push(tu);
                    }
                } else if let Some(e) = otherwise {
                    let eu = self.evaluate(e, inst, &join_path(&parent_path, "else"), inst_path);
                    if !eu.valid {
                        u.valid = false;
                    }
                    u.children.push(eu);
                }
                u
            }
            Kind::UnevaluatedProperties { schema, parent } => {
                let (schema, parent) = (schema.clone(), *parent);
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Object(o) = inst {
                    let evaluated = self.evaluated_properties(parent, id, inst, inst_path);
                    let mut unexpected = Vec::new();
                    for (k, v) in o {
                        if evaluated.contains(k) {
                            continue;
                        }
                        let ipath = join_path(inst_path, k);
                        match &schema {
                            Sub::False => {
                                let cu = Unit::new(true, eval_path, &ipath, self.nodes[id].location.display())
                                    .with_error("falseSchema", format!("False schema does not allow {}", fmt(v)));
                                u.children.push(cu);
                                unexpected.push(k.clone());
                            }
                            Sub::Node(sub) => {
                                let cu = self.evaluate(*sub, v, eval_path, &ipath);
                                if !cu.valid {
                                    u.children.push(cu);
                                    unexpected.push(k.clone());
                                }
                            }
                        }
                    }
                    if !unexpected.is_empty() {
                        u = u.with_error(
                            "unevaluatedProperties",
                            format!("Unevaluated properties are not allowed {}", unexpected_list(&unexpected)),
                        );
                    }
                }
                u
            }
            Kind::UnevaluatedItems { schema, parent } => {
                let (schema, parent) = (schema.clone(), *parent);
                let mut u = Unit::new(true, eval_path, inst_path, loc);
                if let Value::Array(a) = inst {
                    let evaluated = self.evaluated_items(parent, id, inst, inst_path);
                    let mut unexpected = Vec::new();
                    for (i, v) in a.iter().enumerate() {
                        if evaluated.contains(&i) {
                            continue;
                        }
                        let ipath = join_idx(inst_path, i);
                        match &schema {
                            Sub::False => {
                                let cu = Unit::new(true, eval_path, &ipath, self.nodes[id].location.display())
                                    .with_error("falseSchema", format!("False schema does not allow {}", fmt(v)));
                                u.children.push(cu);
                                unexpected.push(fmt(v));
                            }
                            Sub::Node(sub) => {
                                let cu = self.evaluate(*sub, v, eval_path, &ipath);
                                if !cu.valid {
                                    u.children.push(cu);
                                    unexpected.push(fmt(v));
                                }
                            }
                        }
                    }
                    if !unexpected.is_empty() {
                        u = u.with_error(
                            "unevaluatedItems",
                            format!("Unevaluated items are not allowed {}", unexpected_list(&unexpected)),
                        );
                    }
                }
                u
            }
            Kind::Ref { target, lazy } => self.ref_evaluate(id, *target, *lazy, inst, eval_path, inst_path),
            Kind::DynamicRef {
                fallback,
                lazy,
                candidates,
                ..
            }
            | Kind::RecursiveRef {
                fallback,
                lazy,
                candidates,
            } => {
                let target = self.resolve_dynamic(*fallback, candidates);
                self.ref_evaluate(id, target, *lazy, inst, eval_path, inst_path)
            }
        }
    }

    fn ref_evaluate(&mut self, id: NodeId, target: NodeId, lazy: bool, inst: &Value, eval_path: &str, inst_path: &str) -> Unit {
        let loc = self.nodes[id].location.display();
        if lazy {
            let key = (id, inst_path.to_string());
            if self.lazy_stack.contains(&key) {
                return Unit::new(true, eval_path, inst_path, loc);
            }
            self.lazy_stack.push(key);
            let mut u = self.evaluate(target, inst, eval_path, inst_path);
            self.lazy_stack.pop();
            u.schema_loc = loc;
            u
        } else {
            let mut u = self.evaluate(target, inst, eval_path, inst_path);
            u.schema_loc = loc;
            u
        }
    }
}

fn parent_of(path: &str) -> String {
    match path.rfind('/') {
        Some(p) => path[..p].to_string(),
        None => String::new(),
    }
}

fn number_cmp(inst: &Value, limit: &Num, pred: impl Fn(Ordering) -> bool) -> bool {
    match inst {
        Value::Number(x) => pred(num::compare(&Num::from_json(x), limit)),
        _ => true,
    }
}
