fn file_url(path: &str) -> String {
    let p = Path::new(path);
    let canonical = std::fs::canonicalize(p).unwrap_or_else(|_| {
        if p.is_absolute() {
            p.to_path_buf()
        } else {
            std::env::current_dir().map(|d| d.join(p)).unwrap_or_else(|_| p.to_path_buf())
        }
    });
    match url::Url::from_file_path(&canonical) {
        Ok(u) => u.to_string(),
        Err(_) => format!("file://{}", canonical.display()),
    }
}

struct Meta {
    output: OutputFormat,
    errors_only: bool,
    schema_path: String,
}

fn print_payload(meta: &Meta, instance: Option<&str>, payload: Value) {
    let mut m = Map::new();
    if let Some(i) = instance {
        m.insert("instance".into(), Value::String(i.to_string()));
    }
    let name = match meta.output {
        OutputFormat::Flag => "flag",
        OutputFormat::List => "list",
        OutputFormat::Hierarchical => "hierarchical",
        OutputFormat::Text => "text",
    };
    m.insert("output".into(), Value::String(name.to_string()));
    m.insert("payload".into(), payload);
    m.insert("schema".into(), Value::String(meta.schema_path.clone()));
    println!("{}", Value::Object(m));
}

fn unit_payload(output: OutputFormat, unit: &Unit) -> Value {
    match output {
        OutputFormat::Flag => {
            let mut m = Map::new();
            m.insert("valid".into(), Value::Bool(unit.valid));
            Value::Object(m)
        }
        OutputFormat::List => {
            let mut details = Vec::new();
            unit.flatten(&mut details);
            let mut m = Map::new();
            m.insert("details".into(), Value::Array(details));
            m.insert("valid".into(), Value::Bool(unit.valid));
            Value::Object(m)
        }
        OutputFormat::Hierarchical => unit.to_json(true),
        OutputFormat::Text => Value::Null,
    }
}

fn main() {
    let matches = build_cli().get_matches();
    if matches.get_flag("version") {
        println!("Version: 0.41.0");
        return;
    }
    let schema_path = matches.get_one::<String>("schema").cloned().unwrap_or_default();
    let instances: Vec<String> = matches
        .get_many::<String>("instances")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let output = match matches.get_one::<String>("output").map(|s| s.as_str()) {
        Some("flag") => OutputFormat::Flag,
        Some("list") => OutputFormat::List,
        Some("hierarchical") => OutputFormat::Hierarchical,
        _ => OutputFormat::Text,
    };
    let errors_only = matches.get_flag("errors_only");
    let assert_format = matches.get_flag("assert_format") && !matches.get_flag("no_assert_format")
        || (matches.get_flag("assert_format") && matches.get_flag("no_assert_format"));
    let forced_draft = matches.get_one::<String>("draft").map(|d| match d.as_str() {
        "4" => Draft::Draft4,
        "6" => Draft::Draft6,
        "7" => Draft::Draft7,
        "2019" => Draft::Draft201909,
        _ => Draft::Draft202012,
    });
    let connect_timeout = matches.get_one::<f64>("connect_timeout").copied();
    let timeout = matches.get_one::<f64>("timeout").copied();
    // Validate that the timeouts can be converted to durations (mimics the
    // behaviour of the reference implementation).
    for t in [connect_timeout, timeout].into_iter().flatten() {
        let _ = std::time::Duration::from_secs_f64(t);
    }

    let meta = Meta {
        output,
        errors_only,
        schema_path: schema_path.clone(),
    };

    // Load the schema document.
    let schema_value = match read_json(&schema_path) {
        Ok(v) => v,
        Err(e) => {
            println!("Error: {}", e);
            exit(1);
        }
    };

    if let Some(cacert) = matches.get_one::<String>("cacert") {
        if let Err(e) = std::fs::read(cacert) {
            println!("Error: Failed to read certificate file '{}': {}", cacert, e);
            exit(1);
        }
    }

    let fetch_cfg = FetchConfig {
        connect_timeout,
        timeout,
    };
    let registry = Registry::new(Draft::Draft202012, fetch_cfg);
    if let Err(e) = registry.add_meta_schemas() {
        println!("Error: {}", e);
        exit(1);
    }

    // Determine draft.
    let draft = match forced_draft {
        Some(d) => d,
        None => match Draft::detect(&schema_value, Draft::Draft202012) {
            Ok(d) => d,
            Err(uri) => {
                if output == OutputFormat::Text {
                    println!(
                        "Schema is invalid. Error: Unknown meta-schema: '{}'. Custom meta-schemas must be registered in the registry before use",
                        uri
                    );
                } else {
                    // The reference implementation attempts to retrieve the meta-schema.
                    match registry.resolve("", &uri, Draft::Draft202012) {
                        Ok(_) => println!(
                            "Error: Unknown meta-schema: '{}'. Custom meta-schemas must be registered in the registry before use",
                            uri
                        ),
                        Err(e) => println!("Error: {}", e),
                    }
                }
                exit(1);
            }
        },
    };

    // Meta-schema validation.
    let meta_unit = {
        let mut compiler = Compiler::new(&registry, draft.ref_ignores_siblings());
        let meta_uri = draft.meta_schema_uri();
        let res = registry.get_resource(meta_uri).expect("meta-schema registered");
        let root = match compiler.compile_root(&res.value, meta_uri, draft) {
            Ok(r) => r,
            Err(e) => {
                println!("Error: {}", e);
                exit(1);
            }
        };
        let mut ev = Evaluator::new(&compiler.nodes);
        if output == OutputFormat::Text {
            let mut errs = Vec::new();
            ev.errors(root, &schema_value, "", &mut errs);
            if let Some(first) = errs.first() {
                println!("Schema is invalid. Error: {}", first);
                exit(1);
            }
            None
        } else {
            let unit = ev.evaluate(root, &schema_value, "", "");
            if !unit.valid {
                print_payload(&meta, None, unit_payload(output, &unit));
                exit(1);
            }
            Some(unit)
        }
    };

    // Register the schema document and compile.
    let base_file = file_url(&schema_path);
    let base = {
        let mut b = base_file.clone();
        if let Some(obj) = schema_value.as_object() {
            if let Some(Value::String(id)) = obj.get(draft.id_keyword()) {
                if let (Ok(parsed), Ok(base_uri)) = (uri::parse(id), uri::parse(&base_file)) {
                    let mut resolved = uri::resolve(&base_uri, &parsed);
                    uri::normalize(&mut resolved);
                    b = resolved.to_string_no_fragment();
                }
            }
        }
        b
    };
    let doc = Rc::new(schema_value.clone());
    let compile_result = (|| -> Result<(Vec<schema::Node>, usize), String> {
        registry.add_document(&base, doc.clone(), draft).map_err(|e| e.0)?;
        if base != base_file {
            registry.add_document(&base_file, doc.clone(), draft).map_err(|e| e.0)?;
        }
        let mut compiler = Compiler::new(&registry, assert_format);
        let root = compiler.compile_root(&schema_value, &base, draft).map_err(|e| e.0)?;
        Ok((compiler.nodes, root))
    })();
    let (nodes, root) = match compile_result {
        Ok(r) => r,
        Err(e) => {
            if output == OutputFormat::Text {
                println!("Schema is invalid. Error: {}", e);
            } else {
                println!("Error: {}", e);
            }
            exit(1);
        }
    };

    if instances.is_empty() {
        if !errors_only {
            match output {
                OutputFormat::Text => println!("Schema is valid"),
                OutputFormat::Flag => {
                    let mut m = Map::new();
                    m.insert("valid".into(), Value::Bool(true));
                    print_payload(&meta, None, Value::Object(m));
                }
                _ => {
                    if let Some(u) = &meta_unit {
                        print_payload(&meta, None, unit_payload(output, u));
                    }
                }
            }
        }
        return;
    }

    let mut any_invalid = false;
    for inst_path in &instances {
        let inst = match read_json(inst_path) {
            Ok(v) => v,
            Err(e) => {
                println!("Error: {}", e);
                exit(1);
            }
        };
        let mut ev = Evaluator::new(&nodes);
        match output {
            OutputFormat::Text => {
                let mut errs = Vec::new();
                ev.errors(root, &inst, "", &mut errs);
                if errs.is_empty() {
                    if !errors_only {
                        println!("{} - VALID", inst_path);
                    }
                } else {
                    any_invalid = true;
                    println!("{} - INVALID. Errors:", inst_path);
                    for (i, e) in errs.iter().enumerate() {
                        println!("{}. {}", i + 1, e);
                    }
                }
            }
            _ => {
                let unit = ev.evaluate(root, &inst, "", "");
                if !unit.valid {
                    any_invalid = true;
                }
                if unit.valid && errors_only {
                    continue;
                }
                print_payload(&meta, Some(inst_path), unit_payload(output, &unit));
            }
        }
    }
    if any_invalid {
        exit(1);
    }
}
