        self.mant.is_zero()
    }

    /// Exact decimal expansion of a finite f64.
    pub fn from_f64_exact(f: f64) -> Option<Decimal> {
        if !f.is_finite() {
            return None;
        }
        if f == 0.0 {
            return Some(Decimal {
                neg: false,
                mant: BigUint::zero(),
                exp: 0,
            });
        }
        let bits = f.to_bits();
        let neg = (bits >> 63) != 0;
        let exp_bits = ((bits >> 52) & 0x7ff) as i64;
        let frac = bits & ((1u64 << 52) - 1);
        let (m, e) = if exp_bits == 0 {
            (frac, -1074i64)
        } else {
            (frac | (1u64 << 52), exp_bits - 1075)
        };
        let m_big = BigUint::from_u128(m as u128);
        let (mant, exp) = if e >= 0 {
            (m_big.mul_pow2(e as u32), 0i64)
        } else {
            let k = (-e) as u32;
            let mut v = m_big;
            let mut left = k;
            while left > 0 {
                let step = left.min(13); // 5^13 fits in u32
                v = v.mul_small(5u32.pow(step));
                left -= step;
            }
            (v, -(k as i64))
        };
        let digits = mant.to_decimal_string();
        let mut d = Decimal {
            neg,
            mant: BigUint::from_digits(digits.trim_start_matches('0')),
            exp,
        };
        d.normalize_from_digits(digits.trim_start_matches('0'));
        Some(d)
    }

