new = """/// Classification of a JSON number for comparison purposes.
#[derive(Clone, Debug)]
pub struct Num {
    pub dec: Decimal,
    pub f: f64,
    pub text: String,
    /// The literal is an integer that fits in i64/u64.
    pub int_literal: bool,
    /// The literal is exactly representable as an f64.
    pub exact_f64: bool,
}

impl Num {
    pub fn from_json(n: &serde_json::Number) -> Num {
        let text = n.to_string();
        let dec = Decimal::parse(&text).unwrap_or(Decimal {
            neg: false,
            mant: BigUint::zero(),
            exp: 0,
        });
        let f = text.parse::<f64>().unwrap_or(0.0);
        let int_literal = n.is_i64() || n.is_u64();
        let exact_f64 = int_literal
            || Decimal::from_f64_exact(f).map_or(false, |d| d == dec);
        Num {
            dec,
            f,
            text,
            int_literal,
            exact_f64,
        }
    }

    pub fn is_integer(&self) -> bool {
        self.dec.is_integer()
    }

    /// Whether a limit of this value drives f64-based comparisons for
    /// non-integer instances.
    fn int_like_limit(&self) -> bool {
        self.int_literal || (self.exact_f64 && self.f.fract() == 0.0)
    }

    /// Whether this instance uses f64 comparisons against int-like limits.
    fn float_instance(&self) -> bool {
        !self.int_literal && self.f.is_finite()
    }
}

/// Compare an instance number with a limit according to the validator rules.
pub fn compare(instance: &Num, limit: &Num) -> Ordering {
    if limit.int_like_limit() && instance.float_instance() {
        instance.f.partial_cmp(&limit.f).unwrap_or(Ordering::Equal)
    } else {
        instance.dec.cmp(&limit.dec)
    }
}

pub fn is_multiple_of(instance: &Num, limit: &Num) -> bool {
    if limit.int_like_limit() && instance.float_instance() {
        let q = instance.f / limit.f;
        q.is_finite() && q.fract() == 0.0
    } else {
        instance.dec.is_multiple_of(&limit.dec)
    }
}

