/// backreferences to non-existent groups) so that `parse_tree` can be used
/// as a syntax check.
fn relax_for_parse(pattern: &str) -> String {
    let chars: Vec<char> = pattern.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    let mut in_class = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            let n = chars[i + 1];
            if !in_class && n.is_ascii_digit() && n != '0' {
                // backreference: replace with a wildcard
                out.push('.');
                i += 2;
                while i < chars.len() && chars[i].is_ascii_digit() {
                    i += 1;
                }
                continue;
            }
            out.push(c);
            out.push(n);
            i += 2;
            continue;
