        return Err(());
    }
    if let Ok(r) = regex::Regex::new(&translated) {
        return Ok((Pattern::Std(r), translated));
    }
    match fancy_regex::Regex::new(pattern) {
        Ok(r) => Ok((Pattern::Fancy(r), pattern.to_string())),
        Err(_) => Err(()),
    }
}

/// Relax constructs that older parsers accepted (stacked quantifiers and
/// backreferences to non-existent groups) so that `parse_tree` can be used
/// as a syntax check.
fn relax_for_parse(pattern: &str) -> String {
    let chars: Vec<char> = pattern.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    let mut in_class = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            let n = chars[i + 1];
            if !in_class && n.is_ascii_digit() && n != '0' {
                // backreference: replace with a wildcard
                out.push('.');
                i += 2;
                while i < chars.len() && chars[i].is_ascii_digit() {
                    i += 1;
                }
                continue;
            }
            out.push(c);
            out.push(n);
            i += 2;
            continue;
        }
        if in_class {
            if c == ']' {
                in_class = false;
            }
            out.push(c);
            i += 1;
            continue;
        }
        if c == '[' {
            in_class = true;
            out.push(c);
            i += 1;
            if i < chars.len() && chars[i] == '^' {
                out.push('^');
                i += 1;
            }
            if i < chars.len() && chars[i] == ']' {
                out.push(']');
                i += 1;
            }
            continue;
        }
        if matches!(c, '*' | '+' | '?') {
            // collapse runs of quantifiers into a single one
            let mut j = i;
            while j < chars.len() && matches!(chars[j], '*' | '+' | '?') {
                j += 1;
            }
            if j - i >= 2 {
                out.push('*');
            } else {
                out.push(c);
            }
            i = j;
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}

/// Check the `regex` format: the pattern must parse.
pub fn is_valid_regex_format(pattern: &str) -> bool {
    if !syntax_precheck(pattern, true) {
        return false;
    }
    let relaxed = relax_for_parse(pattern);
    fancy_regex::Expr::parse_tree(&relaxed).is_ok()
}
