                }
                Some('(') => {
                    if !self.parse_group(depth) {
                        return false;
                    }
                }
                Some('[') => {
                    if !self.parse_class() {
                        return false;
                    }
                }
                Some('\\') => {
                    if !self.parse_escape(false) {
                        return false;
                    }
                }
                Some(_) => {
                    self.i += 1;
                }
            }
            if !self.parse_quantifiers() {
                return false;
            }
        }
