    /// Length of a `{n}`, `{n,}` or `{n,m}` quantifier at the current position.
    fn quantifier_len(&self) -> Option<usize> {
        let mut j = self.i + 1;
        let mut digits = 0;
        while j < self.c.len() && self.c[j].is_ascii_digit() {
            j += 1;
            digits += 1;
        }
        if digits == 0 {
            return None;
        }
        if j < self.c.len() && self.c[j] == ',' {
            j += 1;
            while j < self.c.len() && self.c[j].is_ascii_digit() {
                j += 1;
            }
