                        return false;
                    }
                    self.i += 1;
                    seen = true;
                    if let Some(c) = self.peek() {
                        if c == '?' || c == '+' {
                            self.i += 1;
                            if matches!(self.peek(), Some('*') | Some('+') | Some('?')) {
                                return false;
                            }
                            if self.peek() == Some('{') && self.quantifier_len().is_some() {
                                return false;
                            }
                        }
                    }
                }
                Some('{') => {
                    match self.quantifier_len() {
                        Some(len) => {
                            if seen {
                                return false;
                            }
                            let body: String = self.c[self.i + 1..self.i + len - 1].iter().collect();
