                                    }
                                }
                            }
                            self.i += len;
                            seen = true;
                            if let Some(c) = self.peek() {
                                if c == '?' || c == '+' {
                                    self.i += 1;
                                    if matches!(self.peek(), Some('*') | Some('+') | Some('?')) {
