        }
        if !self.parse_alternation(depth + 1) {
            return false;
        }
        if self.peek() != Some(')') {
            return false;
        }
        self.i += 1;
        true
    }

    fn parse_group_name(&mut self, close: char) -> bool {
        let start = self.i;
        while let Some(c) = self.peek() {
            if c == close {
                break;
            }
            if !(c.is_ascii_alphanumeric() || c == '_') {
                return false;
            }
            self.i += 1;
        }
        if self.i == start || self.peek() != Some(close) {
            return false;
        }
        if self.c[start].is_ascii_digit() {
            return false;
        }
        self.i += 1;
        true
    }

