            c if c.is_ascii_alphanumeric() => false,
            c if !c.is_ascii() => false,
            _ => true,
        }
    }

    fn parse_class(&mut self) -> bool {
        // at '['
        self.i += 1;
        if self.peek() == Some('^') {
            self.i += 1;
        }
        let mut first = true;
        let mut prev: Option<char> = None; // last literal char (for ranges)
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => return false,
            };
            if c == ']' && !first {
                self.i += 1;
                return true;
            }
            first = false;
            if c == '[' {
                // POSIX class or nested class
                if self.c.get(self.i + 1) == Some(&':') {
                    let rest: String = self.c[self.i..].iter().collect();
                    match rest.find(":]") {
                        Some(end) => {
                            let name = &rest[2..end];
                            const POSIX: &[&str] = &[
                                "alnum", "alpha", "ascii", "blank", "cntrl", "digit", "graph", "lower", "print", "punct",
                                "space", "upper", "word", "xdigit",
                            ];
                            let name = name.strip_prefix('^').unwrap_or(name);
                            if !POSIX.contains(&name) {
                                return false;
                            }
                            self.i += end + 2;
                            prev = None;
                            continue;
                        }
                        None => return false,
                    }
                }
                if !self.parse_class() {
                    return false;
                }
                prev = None;
                continue;
            }
            let mut literal: Option<char> = None;
            if c == '\\' {
                let esc_start = self.i;
                if !self.parse_escape(true) {
                    return false;
                }
                let e = self.c[esc_start + 1];
                if !(e.is_ascii_alphanumeric()) {
                    literal = Some(e);
                }
            } else {
                self.i += 1;
                literal = Some(c);
            }
            // range?
            if self.peek() == Some('-') && self.c.get(self.i + 1).map_or(false, |&n| n != ']') {
                self.i += 1;
                let hi_start = self.i;
                let hi = match self.peek() {
                    Some('\\') => {
                        if !self.parse_escape(true) {
                            return false;
                        }
                        let e = self.c[hi_start + 1];
                        if e.is_ascii_alphanumeric() {
                            None
                        } else {
                            Some(e)
                        }
                    }
                    Some('[') => return false,
                    Some(h) => {
                        self.i += 1;
                        Some(h)
                    }
                    None => return false,
                };
                match (literal, hi) {
                    (Some(lo), Some(hi)) => {
                        if lo > hi {
                            return false;
                        }
                    }
                    _ => return false,
                }
                prev = None;
                continue;
            }
            prev = literal;
        }
        #[allow(unreachable_code)]
        {
            let _ = prev;
            true
        }
    }
}

/// Validate regex syntax the way the reference engine does.
fn syntax_ok(pattern: &str) -> bool {
    let chars: Vec<char> = pattern.chars().collect();
    let mut ck = Checker {
        c: &chars,
        i: 0,
        group_count: 0,
    };
    if !ck.parse_alternation(0) {
        return false;
    }
    ck.i == chars.len()
}

/// Compile a `pattern` keyword value. Returns the compiled regex and the
/// pattern text used in error messages.
pub fn compile(pattern: &str) -> Result<(Pattern, String), ()> {
    if !syntax_ok(pattern) {
        return Err(());
    }
    let translated = translate(pattern);
    if fancy_regex::Regex::new(&translated).is_err() && fancy_regex::Regex::new(pattern).is_err() {
        return Err(());
    }
    if let Ok(r) = regex::Regex::new(&translated) {
        return Ok((Pattern::Std(r), translated));
    }
    match fancy_regex::Regex::new(pattern) {
        Ok(r) => Ok((Pattern::Fancy(r), pattern.to_string())),
        Err(_) => Err(()),
    }
}

/// Check the `regex` format: the pattern must parse.
pub fn is_valid_regex_format(pattern: &str) -> bool {
    syntax_ok(pattern)
}
