/// Validate regex syntax the way the reference engine does.
fn syntax_ok(pattern: &str) -> bool {
    let chars: Vec<char> = pattern.chars().collect();
    let mut ck = Checker {
        c: &chars,
        i: 0,
        group_count: 0,
    };
    if !ck.parse_alternation(0) {
        return false;
    }
    ck.i == chars.len()
}

/// Compile a `pattern` keyword value. Returns the compiled regex and the
/// pattern text used in error messages.
pub fn compile(pattern: &str) -> Result<(Pattern, String), ()> {
    if !syntax_ok(pattern) {
        return Err(());
    }
    let translated = translate(pattern);
    if fancy_regex::Regex::new(&translated).is_err() && fancy_regex::Regex::new(pattern).is_err() {
        return Err(());
    }
    if let Ok(r) = regex::Regex::new(&translated) {
        return Ok((Pattern::Std(r), translated));
    }
    match fancy_regex::Regex::new(pattern) {
        Ok(r) => Ok((Pattern::Fancy(r), pattern.to_string())),
        Err(_) => Err(()),
    }
}

/// Check the `regex` format: the pattern must parse.
pub fn is_valid_regex_format(pattern: &str) -> bool {
    syntax_ok(pattern)
}
