for idx, sch in enumerate(["not a uri", "http://json-schema.org/draft-03/schema#", "urn:foo", "other.json", "http://example.com/x", "ftp://x/y", "file:///nonexistent/x.json", "https://json-schema.org/draft-07/schema#", "http://json-schema.org/draft-07/schema"]):
    for args in (["--output", "flag"], [], ["-d", "7"], ["-d", "7", "--output", "list"]):
        add(f"r6/schema_kw/{idx}/{'_'.join(args) or 'text'}", {"$schema": sch, "type": "string"}, ["1"], args)
EOF
python3 harness.py record-missing /tmp/t/orig cases.py expected.json 2>&1 | tail -1; timeout 170 python3 harness.py compare ../target/release/jsonschema-cli cases.py expected.json r6/ 2>&1 | tail -1; cd /workspace && git add -A . && git commit -qm "\$schema URI validation with forced drafts; unknown meta-schema fetch errors" && echo ok"}

{"command":"cd /workspace && python3 - <<'EOF'
p='src/main.rs'
s=open(p).read()
old = """    // Determine draft.
    let draft = match forced_draft {
        Some(d) => d,"""
new = """    // Determine draft.
    let draft = match forced_draft {
        Some(d) => {
            // Relative `$schema` references cannot be resolved in the
            // structured output modes.
            if output != OutputFormat::Text {
                if let Some(Value::String(uri_str)) = &schema_kw {
                    if uri::parse(uri_str).map(|u| u.scheme.is_none()).unwrap_or(false) {
                        println!(
                            "Error: Resource '{}' is not present in a registry and retrieving it failed: Unknown scheme json-schema",
                            uri_str
                        );
                        exit(1);
                    }
                }
            }
            d
        }"""
assert old in s
s = s.replace(old, new)
open(p,'w').write(s)
EOF
cargo build --release --offline 2>&1 | grep -E "^(warning|error)" -A 6 | head -20; cd tests && timeout 170 python3 harness.py compare ../target/release/jsonschema-cli cases.py expected.json r6/ 2>&1 | tail -1; cd /tmp/t && echo '{"$schema":"#frag","type":"string"}' > _s.json; for args in "-d 7 --output flag" "--output flag" "" "-d 7"; do a=$(/tmp/t/orig _s.json -i _i.json $args 2>&1); b=$(/workspace/target/release/jsonschema-cli _s.json -i _i.json $args 2>&1); [ "$a" == "$b" ] && echo "same: $(echo $a | cut -c1-100)" || echo "DIFF [$a] [$b]"; done"}

